 You can use Express middleware to capture and log all traffic requests. Middleware functions in Express have access to the request and response objects, and they're executed in the order they're defined.

Here's how you can add logging middleware to your application:

```javascript
const express = require("express");
const app = express();
require("dotenv").config();

// Add logging middleware - place this BEFORE other middleware
app.use((req, res, next) => {
  const start = Date.now();

  // Log request details
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  console.log('Request Headers:', req.headers);
  console.log('Request Body:', req.body);

  // Capture response
  const originalSend = res.send;
  res.send = function(body) {
    console.log(`[${new Date().toISOString()}] Response Status: ${res.statusCode}`);
    console.log('Response Body:', body);
    console.log(`Request took ${Date.now() - start}ms`);
    console.log('-----------------------------------');
    return originalSend.call(this, body);
  };

  next();
});

app.use(express.json());

// Route Modules
const githubRoutes = require("./routes/github");
const notionRoutes = require("./routes/notion");
app.use("/github", githubRoutes);
app.use("/notion", notionRoutes);

// Health Check
app.get("/", (req, res) => {
  res.send("✅ Notion + GitHub Full API is live.");
});

app.listen(3000, () => {
  console.log("🚀 Server is running on port 3000");
});

const path = require("path");
// Serve the OpenAPI spec file
app.get("/openapi.json", (req, res) => {
  res.sendFile(path.join(__dirname, "openapi.json"));
});
```

Important notes:
1. The logging middleware is placed before `express.json()` to ensure it catches all requests
2. You'll see request body as empty for GET requests, which is normal
3. The middleware captures the request method, URL, headers, body, response status, and response body
4. It also tracks the time taken to process each request

This approach gives you a comprehensive view of all traffic going through your Express application.

Would you like me to explain how this middleware works in more detail?

