import os
import sys
import subprocess
import zipfile
import platform
from pathlib import Path
import getpass
import requests
import shutil
import webbrowser
import time
import stat

REPOS = {
    "LLM_Unchained_Admin_Rebuild.zip": "llm-unchained-admin",
    "LLM_Unchained_Backend_Rebuild.zip": "llm-unchained-backend",
    "LLM_Unchained_Mobile_Rebuild.zip": "llm-unchained-mobile"
}

def is_installed(cmd):
    return shutil.which(cmd) is not None

def run_cmd(cmd, cwd=None):
    try:
        # Use subprocess list form to avoid quote issues
        if platform.system() == "Windows":
            # On Windows, use shell=True for convenience but with careful string formatting
            result = subprocess.run(cmd, shell=True, cwd=cwd, check=False)
        else:
            # On Unix systems, we can use shell=False with args as list for better safety
            if isinstance(cmd, str):
                cmd_args = cmd.split()
            else:
                cmd_args = cmd
            result = subprocess.run(cmd_args, shell=False, cwd=cwd, check=False)
            
        if result.returncode != 0:
            print(f"Command failed: {cmd}")
            print(f"Return code: {result.returncode}")
            # Don't exit on failure, just report and continue
            return False
        return True
    except Exception as e:
        print(f"Error executing command: {cmd}")
        print(f"Error details: {str(e)}")
        # Don't exit on failure, just report and continue
        return False

def install_or_prompt(tool, win_url=None, mac_cmd=None, linux_cmd=None):
    if is_installed(tool):
        print(f"{tool} is installed")
        return

    print(f"{tool} is not installed")
    system = platform.system()
    
    if system == "Windows":
        if tool == "git":
            run_cmd("winget install --id Git.Git -e --silent")
        elif tool == "python":
            run_cmd("winget install --id Python.Python.3 -e --silent")
        else:
            print(f"Please install {tool} from: {win_url}")
            webbrowser.open(win_url)
            input(f"Press Enter after you've installed {tool}...")
    elif system == "Darwin" and mac_cmd:  # macOS
        run_cmd(mac_cmd)
    elif system == "Linux" and linux_cmd:
        run_cmd(linux_cmd)
    else:
        print(f"Please install {tool} manually.")
        sys.exit(1)

    # Verify installation was successful
    if not is_installed(tool):
        print(f"Installation of {tool} seems to have failed. Please install manually.")
        sys.exit(1)

def check_repo_exists(repo_name, token, username):
    print(f"Checking if repository {repo_name} exists...")
    headers = {
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json"
    }
    
    try:
        response = requests.get(f"https://api.github.com/repos/{username}/{repo_name}", headers=headers)
        return response.status_code == 200
    except requests.exceptions.RequestException as e:
        print(f"Network error when checking repo: {str(e)}")
        sys.exit(1)

def create_repo(repo_name, token, username):
    # First check if repo exists
    if check_repo_exists(repo_name, token, username):
        print(f"Repository {repo_name} already exists, skipping creation.")
        return True
        
    print(f"Creating GitHub repo: {repo_name}")
    headers = {
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json"
    }
    data = {"name": repo_name, "private": False}
    try:
        r = requests.post("https://api.github.com/user/repos", headers=headers, json=data)
        if r.status_code == 201:
            print(f"Repo {repo_name} created successfully.")
            return True
        elif r.status_code == 422 and "already exists" in r.text:
            print(f"Repo {repo_name} already exists.")
            return True
        else:
            print(f"Error creating repo: {r.status_code}")
            print(f"Response: {r.text}")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Network error when creating repo: {str(e)}")
        return False

def remove_readonly(func, path, _):
    """Clear the readonly bit and reattempt the removal"""
    os.chmod(path, stat.S_IWRITE)
    func(path)

def safe_remove_folder(folder_path):
    """Safely remove a folder, handling git repositories and read-only files"""
    if not os.path.exists(folder_path):
        return True
    
    print(f"Removing existing folder: {folder_path}")
    
    # First try to reset git if it's a git repo
    if os.path.exists(os.path.join(folder_path, ".git")):
        try:
            # Try to clean git and release locks
            run_cmd("git reset --hard", cwd=folder_path)
            run_cmd("git clean -fd", cwd=folder_path)
        except:
            # Continue even if git commands fail
            pass
    
    # Wait a moment to ensure processes are closed
    time.sleep(1)
    
    # Try multiple removal methods
    try_count = 0
    max_tries = 3
    while try_count < max_tries and os.path.exists(folder_path):
        try_count += 1
        try:
            print(f"Removal attempt {try_count}/{max_tries}...")
            
            # Try using shutil
            try:
                shutil.rmtree(folder_path)
                if not os.path.exists(folder_path):
                    return True
            except Exception as e:
                print(f"Standard removal failed: {str(e)}")
            
            # Try with onerror handler
            try:
                shutil.rmtree(folder_path, onerror=remove_readonly)
                if not os.path.exists(folder_path):
                    return True
            except Exception as e:
                print(f"Enhanced removal failed: {str(e)}")
            
            # Try system command if still exists
            if platform.system() == "Windows" and os.path.exists(folder_path):
                try:
                    # Force using system command 
                    os.system(f'rd /s /q "{folder_path}"')
                    if not os.path.exists(folder_path):
                        return True
                except Exception as e:
                    print(f"System command removal failed: {str(e)}")
            
            # Small delay between attempts
            time.sleep(2)
            
        except Exception as e:
            print(f"Removal attempt {try_count} failed: {str(e)}")
    
    # If we still can't remove it, ask the user what to do
    if os.path.exists(folder_path):
        print(f"Warning: Could not remove folder {folder_path} after {max_tries} attempts")
        return False
    
    return True

def unzip_and_push(zip_name, repo_name, token, username, repo_exists=False):
    folder = Path(zip_name).stem
    
    # Clean up existing folder if it exists
    if not safe_remove_folder(folder):
        user_input = input(f"Folder '{folder}' could not be removed. Continue anyway? (y/n): ")
        if user_input.lower() != 'y':
            print("Operation cancelled by user")
            return False
    
    # Unzip the file using Python's built-in zipfile module
    print(f"Unzipping {zip_name}...")
    try:
        with zipfile.ZipFile(zip_name, 'r') as zip_ref:
            zip_ref.extractall(folder)
    except zipfile.BadZipFile:
        print(f"Error: {zip_name} is not a valid zip file")
        return False
    except Exception as e:
        print(f"Error unzipping {zip_name}: {str(e)}")
        return False
    
    # Save current directory to return to it later
    original_dir = os.getcwd()
    success = False
    
    try:
        os.chdir(folder)
        
        if repo_exists:
            print(f"Repository {repo_name} exists, updating...")
            # For an existing repo, clone it first, then update contents
            temp_folder = f"{folder}_temp"
            if os.path.exists(temp_folder):
                safe_remove_folder(temp_folder)
                
            os.chdir(original_dir)  # Go back to original dir
            clone_success = run_cmd(f'git clone "https://{username}:{token}@github.com/{username}/{repo_name}.git" "{temp_folder}"')
            
            if clone_success and os.path.exists(temp_folder):
                # Copy .git folder from clone to preserve history
                git_folder = os.path.join(temp_folder, ".git")
                if os.path.exists(git_folder):
                    try:
                        shutil.copytree(git_folder, os.path.join(folder, ".git"), dirs_exist_ok=True)
                    except Exception as e:
                        print(f"Error copying .git folder: {str(e)}")
                        # If copy fails, we'll initialize a new git repo
                        clone_success = False
                
                # Remove temp folder
                safe_remove_folder(temp_folder)
            else:
                print("Failed to clone repository, will recreate it instead.")
                clone_success = False
            
            # Go back to working folder
            os.chdir(folder)
            
            if clone_success:
                # Add all files and commit
                run_cmd("git add --all")
                run_cmd("git config --local user.email \"auto@example.com\"")
                run_cmd("git config --local user.name \"Auto Publisher\"")
                # Use double quotes for Windows compatibility
                commit_success = run_cmd("git commit -m \"Update repository content\"")
                if commit_success:
                    # Push to update the repo
                    push_success = run_cmd("git push origin main")
                    success = push_success
                else:
                    print("Commit failed, possibly nothing to commit")
                    success = True  # Consider it a success if there were no changes
            else:
                # Fall back to creating a new repo if clone/update failed
                print("Falling back to repository recreation...")
                repo_exists = False
        
        if not repo_exists:
            print(f"Initializing git and pushing {repo_name}...")
            run_cmd("git init")
            run_cmd("git add --all")
            run_cmd("git config --local user.email \"auto@example.com\"")
            run_cmd("git config --local user.name \"Auto Publisher\"")
            # Use double quotes for Windows compatibility
            commit_success = run_cmd("git commit -m \"Initial commit\"")
            
            if commit_success:
                run_cmd("git branch -M main")
                # Use https token authentication with quotes around URL
                remote_add_success = run_cmd(f'git remote add origin "https://{username}:{token}@github.com/{username}/{repo_name}.git"')
                
                if remote_add_success:
                    push_success = run_cmd("git push -u origin main")
                    success = push_success
            else:
                print("Failed to create initial commit")
                success = False
    except Exception as e:
        print(f"Error in git operations: {str(e)}")
        success = False
    finally:
        # Always return to original directory
        os.chdir(original_dir)
    
    return success

def main():
    print("=== LLM Unchained Auto-Publisher ===")
    
    # Check for required dependencies - only git and Python are needed
    install_or_prompt("git", "https://git-scm.com/downloads", "brew install git", "sudo apt install git -y || sudo yum install git -y")
    
    # Check for Python (looking for both 'python' and 'python3' commands)
    if not is_installed("python") and not is_installed("python3"):
        install_or_prompt("python", "https://www.python.org/downloads/", "brew install python3", "sudo apt install python3 -y || sudo yum install python3 -y")
    
    # Get GitHub credentials
    username = input("GitHub Username: ")
    if not username:
        print("Username cannot be empty")
        sys.exit(1)
        
    token = input("GitHub Personal Access Token: ")
    if not token:
        print("Token cannot be empty")
        sys.exit(1)
    
    # Validate token has required permissions (just a basic check)
    try:
        test_headers = {"Authorization": f"token {token}", "Accept": "application/vnd.github.v3+json"}
        test_response = requests.get("https://api.github.com/user", headers=test_headers)
        if test_response.status_code != 200:
            print(f"Token validation failed. Please check your token has correct permissions.")
            sys.exit(1)
    except requests.exceptions.RequestException:
        print("Could not validate token. Check your internet connection.")
        sys.exit(1)
    
    # Process each repository
    missing_files = []
    successful_repos = []
    failed_repos = []
    
    for zip_file, repo in REPOS.items():
        if not Path(zip_file).exists():
            print(f"Missing {zip_file}, skipping...")
            missing_files.append(zip_file)
            continue
        
        try:
            # Check if repo exists
            repo_exists = check_repo_exists(repo, token, username)
            
            if not repo_exists:
                # Create repo only if it doesn't exist
                create_success = create_repo(repo, token, username)
                if not create_success:
                    print(f"Failed to create repository {repo}")
                    failed_repos.append(repo)
                    continue
            
            # Update or initialize repo
            success = unzip_and_push(zip_file, repo, token, username, repo_exists)
            
            if success:
                action = "Updated" if repo_exists else "Published"
                print(f"Successfully {action} {repo}")
                successful_repos.append(repo)
            else:
                print(f"Failed to {('update' if repo_exists else 'publish')} {repo}")
                failed_repos.append(repo)
        except Exception as e:
            print(f"Error processing {zip_file}: {str(e)}")
            failed_repos.append(repo)
    
    # Summary
    print("\n=== Summary ===")
    
    if successful_repos:
        print("\nSuccessfully published/updated repositories:")
        for repo in successful_repos:
            print(f"  - {repo}")
    
    if failed_repos:
        print("\nFailed to publish/update repositories:")
        for repo in failed_repos:
            print(f"  - {repo}")
    
    if missing_files:
        print("\nMissing zip files:")
        for file in missing_files:
            print(f"  - {file}")
    
    print("\nAll done! Your successful projects are live on GitHub.")

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nOperation cancelled by user")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {str(e)}")
        sys.exit(1)

