    if os.path.exists(os.path.join(folder_path, ".git")):
        try:
            run_cmd("git reset --hard", cwd=folder_path)
            run_cmd("git clean -fd", cwd=folder_path)
        except:
            pass

    # Wait a moment to ensure processes are closed
    time.sleep(1)

    # Try multiple removal methods
    try_count = 0
    max_tries = 3
    while try_count < max_tries and os.path.exists(folder_path):
        try_count += 1
        try:
            print(f"Removal attempt {try_count}/{max_tries}...")

            # On Windows, try to remove read-only attributes from all files first
            if platform.system() == "Windows":
                try:
                    # Recursively change file attributes
                    for root, dirs, files in os.walk(folder_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            try:
                                os.chmod(file_path, stat.S_IWRITE)
                            except:
                                pass

                    # Wait briefly for file system to update
                    time.sleep(0.5)
                except Exception as e:
                    print(f"Error removing read-only attributes: {str(e)}")

            # Try using shutil
            try:
                shutil.rmtree(folder_path)
                if not os.path.exists(folder_path):
                    return True
            except Exception as e:
