          ]
        }
      },
      {
        headers: {
          Authorization: `Bearer ${notionToken}`,
          "Notion-Version": "2022-06-28",
          "Content-Type": "application/json"
        }
      }
    );

    return res.json({ success: true, message: `Memory line updated for key '${key}'.` });
  } catch (error) {
    console.error("❌ update-memory error:", error.response?.data || error.message);
    return res.status(500).json({ error: error.response?.data || error.message });
  }
});

// === DELETE /notion/delete-memory ===
router.delete("/delete-memory", async (req, res) => {
  const { key } = req.body;

  if (!memoryPageId || !key) {
    return res.status(400).json({ error: "Missing GPT_MEMORY or key." });
  }

  try {
    const blocksRes = await axios.get(
      `https://api.notion.com/v1/blocks/${memoryPageId}/children?page_size=100`,
      {
        headers: {
          Authorization: `Bearer ${notionToken}`,
          "Notion-Version": "2022-06-28",
          "Content-Type": "application/json"
        }
      }
    );

    const blocks = blocksRes.data.results;
    const match = blocks.find(block => {
      const text = block[block.type]?.rich_text?.map(rt => rt.text?.content).join("") || "";
      return text.trim().startsWith(`${key}:`);
    });

    if (!match) {
      return res.status(404).json({ error: `No memory line found with key '${key}'.` });
    }

    const blockId = match.id;

    await axios.delete(`https://api.notion.com/v1/blocks/${blockId}`, {
      headers: {
        Authorization: `Bearer ${notionToken}`,
        "Notion-Version": "2022-06-28",
        "Content-Type": "application/json"
      }
    });

    return res.json({ success: true, message: `Memory line '${key}' deleted.` });
  } catch (error) {
    console.error("❌ delete-memory error:", error.response?.data || error.message);
    return res.status(500).json({ error: error.response?.data || error.message });
  }
});

module.exports = router;

