// === Utility: Find Versioned Page Title ===
async function findNextVersionedTitle(baseTitle, maxAttempts = 10) {
  // Escape regex special characters in baseTitle for safe matching
  const safeTitle = baseTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const titleRegex = new RegExp(`^${safeTitle}\\s+(\\d+)$`);

  try {
    // Search for pages with similar titles
    const searchResults = await apiCallWithRetry(() => 
      notionApi.post('/search', {
        query: baseTitle,
        filter: { property: "object", value: "page" }
      })
    );

    // Track highest version number
    let highestVersion = 0;

    // Check all search results to find existing versions
    await Promise.all(searchResults.data.results.map(async (page) => {
      const extractedTitle = await extractPageTitle(page);
      if (extractedTitle) {
        const match = extractedTitle.match(titleRegex);
        if (match) {
          const version = parseInt(match[1], 10);
          if (!isNaN(version) && version > highestVersion) {
            highestVersion = version;
          }
        }
      }
    }));

    // Also check if the base title exists
    const baseExists = await findPageByTitle(baseTitle);

    // If base title doesn't exist, use it first
    if (!baseExists) {
      return { 
        title: baseTitle, 
        isNew: true, 
        version: 0 
      };
    }

    // Calculate next version number
    const newVersion = highestVersion + 1;
    const newTitle = `${baseTitle} ${newVersion}`;

    // Verify this title is actually available (to be extra safe)
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const attemptTitle = `${baseTitle} ${newVersion + attempt}`;
      const exists = await findPageByTitle(attemptTitle);

      if (!exists) {
        return {
          title: attemptTitle,
          isNew: true,
          version: newVersion + attempt
        };
      }
    }

    throw new Error(`Failed to find available version for "${baseTitle}" after ${maxAttempts} attempts`);
  } catch (error) {
    console.error(`❌ Version checking failed:`, error.message);
    // Fallback to timestamp for safety
    const timestamp = Date.now().toString().slice(-6);
    return {
      title: `${baseTitle} ${timestamp}`,
      isNew: true,
      version: null,
      isTimestamped: true
    };
  }
}

