// === Create Page with Content Chunking ===
async function createPageWithChunks(title, content, parentId = notionParentPageId, images = []) {
  // First, create the page with initial properties and metadata
  console.log(`Creating page titled "${title}" with chunked content...`);

  const createRes = await apiCallWithRetry(() => 
    notionApi.post('/pages', {
      parent: { type: "page_id", page_id: parentId },
      properties: {
        title: [
          {
