  );

  const pageId = createRes.data.id;
  console.log(`✅ Created page with ID: ${pageId}, now adding content chunks...`);

  // Process content in chunks
  const contentChunks = chunkContent(content);
  console.log(`Content split into ${contentChunks.length} chunks of max 500 words each`);

  // Add content chunks in batches
  for (let i = 0; i < contentChunks.length; i++) {
    console.log(`Adding chunk ${i+1}/${contentChunks.length}...`);

    await apiCallWithRetry(() => 
      notionApi.patch(`/blocks/${pageId}/children`, {
        children: [createParagraphBlock(contentChunks[i])]
      })
    );

    // Add a small delay to avoid rate limiting
    if (i < contentChunks.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 300));
    }
  }

  // Process images one at a time if any
  if (images && images.length > 0) {
    console.log(`Processing ${images.length} images one by one...`);

    for (let i = 0; i < images.length; i++) {
      console.log(`Adding image ${i+1}/${images.length}...`);

      const imageBlock = processImages(images[i]);

      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: imageBlock
        })
      );

      // Add a small delay between image uploads
      if (i < images.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  }

  console.log(`✅ Successfully added all content to page "${title}"`);
  return pageId;
}

