async function extractChildPagesBreadthFirst(rootPageId, maxDepth = 5) {
  const visited = new Set();
  const queue = [{ id: rootPageId, depth: 0 }];
  const pages = [];

  while (queue.length > 0) {
    const { id: pageId, depth } = queue.shift();

    if (visited.has(pageId) || depth > maxDepth) continue;
    visited.add(pageId);

    try {
      const response = await apiCallWithRetry(() => 
        notionApi.get(`/blocks/${pageId}/children?page_size=100`)
      );

      for (const block of response.data.results) {
        if (block.type === "child_page") {
          const childId = block.id;
          let childTitle = block.child_page?.title || "(no title)";

          pages.push({
            id: childId,
            title: childTitle,
            parent: pageId,
            type: "page"
          });

          if (depth + 1 <= maxDepth) {
            queue.push({ id: childId, depth: depth + 1 });
          }
        }
      }
    } catch (err) {
      console.error(`Failed to fetch children for ${pageId}:`, err.message);
    }
  }

  return pages;
}
