async function extractChildPagesBreadthFirst(rootPageId, maxDepth = 5) {
  const visited = new Set();
  const queue = [{ id: rootPageId, depth: 0 }];
  const pages = [];

  while (queue.length > 0) {
    const { id: pageId, depth } = queue.shift();

    if (visited.has(pageId) || depth > maxDepth) continue;
    visited.add(pageId);

    try {
      const response = await apiCallWithRetry(() => 
        notionApi.get(`/blocks/${pageId}/children?page_size=100`)
      );

      for (const block of response.data.results) {
        if (block.type === "child_page") {
          const childId = block.id;
          let childTitle = block.child_page?.title || "(no title)";

          pages.push({
            id: childId,
            title: childTitle,
            parent: pageId,
            type: "page"
          });

          if (depth + 1 <= maxDepth) {
            queue.push({ id: childId, depth: depth + 1 });
          }
        }
      }
    } catch (err) {
      console.error(`Failed to fetch children for ${pageId}:`, err.message);
    }
  }

  return pages;
}
```

### 2. Implement Request Throttling

The current code has small delays between requests, but a more robust rate limiter would prevent 429 errors:

```javascript
// Add this utility for better rate limiting
const rateLimiter = {
  queue: [],
  processing: false,
  minDelay: 200, // 200ms minimum between requests
  lastRequest: 0,

  async add(fn) {
    return new Promise((resolve, reject) => {
      this.queue.push({ fn, resolve, reject });
      if (!this.processing) this.processQueue();
    });
  },

  async processQueue() {
    if (this.queue.length === 0) {
      this.processing = false;
      return;
    }

    this.processing = true;
    const now = Date.now();
    const timeToWait = Math.max(0, this.lastRequest + this.minDelay - now);

    if (timeToWait > 0) {
      await new Promise(resolve => setTimeout(resolve, timeToWait));
    }

    const { fn, resolve, reject } = this.queue.shift();
    this.lastRequest = Date.now();

    try {
      const result = await fn();
      resolve(result);
    } catch (error) {
      reject(error);
    } finally {
      this.processQueue();
    }
  }
};

// Then update apiCallWithRetry to use the rate limiter
async function apiCallWithRetry(fn, maxRetries = 3) {
  let retries = 0;
  while (true) {
    try {
      return await rateLimiter.add(fn);
    } catch (error) {
      if (error.response?.status === 429 && retries < maxRetries) {
        const delay = Math.pow(2, retries) * 1000;
        console.log(`Rate limited, retrying in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        throw error;
      }
    }
  }
}
```

