const express = require("express");
const router = express.Router();
const axios = require("axios");

// === Environment Variables Validation ===
const requiredEnvVars = ['NOTION_TOKEN', 'NOTION_PARENT_PAGE_ID'];
const missingVars = requiredEnvVars.filter(v => !process.env[v]);
if (missingVars.length) {
  console.error(`❌ Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

const notionToken = process.env.NOTION_TOKEN;
const notionParentPageId = process.env.NOTION_PARENT_PAGE_ID;
const notionDatabaseId = process.env.NOTION_DATABASE_ID;
const notionMemoryDBId = process.env.GPT_MEMORY;

// === Create Axios Instance with Default Configuration ===
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${notionToken}`,
// [FIX-001] Possible floating key-value pair on line 25. Check context.
//     "Content-Type": "application/json"
  }
});

// === Simplified and Unified Caching Setup ===
const cache = {
  data: new Map(),
  ttl: 1000 * 60 * 5,

  set(key, value, namespace = 'default') {
    this.data.set(`${namespace}:${key}`, { value, timestamp: Date.now() });
  },
  get(key, namespace = 'default') {
    const item = this.data.get(`${namespace}:${key}`);
    if (!item || (Date.now() - item.timestamp) > this.ttl) {
      this.data.delete(`${namespace}:${key}`);
      return null;
    }
    return item.value;
  },
  invalidate(key, namespace = 'default') {
    this.data.delete(`${namespace}:${key}`);
  },
  clear(namespace = null) {
    if (!namespace) this.data.clear();
    else {
      for (let key of this.data.keys()) {
        if (key.startsWith(`${namespace}:`)) this.data.delete(key);
      }
    }
  }
};

// === Error Handling Helper ===
const handleApiError = (res, error, context) => {
  console.error(`❌ ${context} error:`, error.response?.data || error.message);
  res.status(error.response?.status || 500).json({ 
    error: error.response?.data || error.message,
    context
  });
};

// === Retry Logic ===
async function apiCallWithRetry(fn, maxRetries = 3) {
  let retries = 0;
  while (true) {
    try {
      return await fn();
    } catch (error) {
      if (error.response?.status === 429 && retries < maxRetries) {
        const delay = Math.pow(2, retries) * 1000;
        console.log(`Rate limited, retrying in ${delay}ms`);
// [FIX-002] Removed invalid placeholder ellipsis from line 76
// [FIX-003] Possible 'await' outside async function on line 77. Ensure valid async context.
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        throw error;
      }
    }
  }
}

// === Consolidated Block Creation Helper ===
function createBlock(type, content, level = 1) {
  if (type === 'heading') {
    type = `heading_${level}`;
  }
  return {
