// === Pagination helper ===
async function paginatedRequest(endpoint, params = {}, pageSize = 100) {
  let results = [];
  let hasMore = true;
  let startCursor = undefined;

  while (hasMore) {
    const queryParams = { params, page_size: pageSize };
// [FIX-012] Removed invalid placeholder ellipsis from line 331
    if (startCursor) {
      queryParams.start_cursor = startCursor;
    }

// [FIX-013] Possible 'await' outside async function on line 336. Ensure valid async context.
    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    });

    results = results.concat(response.data.results);
    hasMore = response.data.has_more;
    startCursor = response.data.next_cursor;

    if (results.length > 1000) {
      console.warn('Pagination limit reached (1000 items)');
      break;
    }
  }

  return results;
}

// === Normalize keys for memory functions ===
function normalizeKey(key) {
  return decodeURIComponent(key.trim().toLowerCase());
}

// === Utility: Content Chunking ===
function chunkContent(content, wordLimit = 500) {
  if (!content) return [];

  const words = content.split(/\s+/);
  const chunks = [];

  for (let i = 0; i < words.length; i += wordLimit) {
    const chunk = words.slice(i, i + wordLimit).join(' ');
    chunks.push(chunk);
  }

  return chunks;
}

// === Utility: Ensure Unique Title ===
async function ensureUniqueTitle(title) {
  let currentTitle = title;
  let counter = 1;
  let match = await findPageByTitle(currentTitle);

  while (match) {
    currentTitle = `${title} ${counter}`;
// [FIX-014] Possible 'await' outside async function on line 386. Ensure valid async context.
    match = await findPageByTitle(currentTitle);
    counter++;

    if (counter > 100) {
      throw new Error(`Unable to generate unique title after 100 attempts for "${title}"`);
    }
  }

  return currentTitle;
}

