  set(key, value, type = 'pages') {
    this[type].set(key, {
      value,
      timestamp: Date.now()
    });
  },
  get(key, type = 'pages') {
    const item = this[type].get(key);
    if (!item) return null;

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this[type].delete(key);
      return null;
    }

    return item.value;
  },
  invalidate(key, type = 'pages') {
    this[type].delete(key);
  },
  clear() {
    this.pages.clear();
    this.titles.clear();
  },
  // Added function to cleanup expired entries proactively
  cleanup() {
    const now = Date.now();
    ['pages', 'titles'].forEach(type => {
      this[type].forEach((item, key) => {
        if (now - item.timestamp > this.ttl) {
          this[type].delete(key);
        }
      });
    });
  }
