  } catch (err) {
    console.error(`Failed to fetch children for ${pageId}:`, err.message);
    return pages;
  }
}

// === Pagination helper with improved error handling ===
async function paginatedRequest(endpoint, params = {}, pageSize = 100, maxItems = 5000) {
  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let requestCount = 0;
  const maxRequests = Math.ceil(maxItems / pageSize);

  while (hasMore && requestCount < maxRequests) {
    const queryParams = { ...params, page_size: pageSize };
    if (startCursor) {
      queryParams.start_cursor = startCursor;
    }

    try {
      const response = await apiCallWithRetry(() => {
        if (endpoint === 'search') {
          return notionApi.post('/search', queryParams);
        } else {
          const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
          return notionApi.get(url, { params: queryParams });
        }
      });

      results = results.concat(response.data.results);
      hasMore = response.data.has_more;
      startCursor = response.data.next_cursor;
      requestCount++;

      // Safety check to prevent excessive memory usage
      if (results.length >= maxItems) {
        console.warn(`Pagination limit reached (${maxItems} items)`);
        break;
      }
    } catch (error) {
      console.error(`Pagination error on request ${requestCount}:`, error.message);
      throw new Error(`Failed during pagination: ${error.message}`);
    }
  }

  return results;
}

