            property: "Key",
            title: { equals: normalizeKey(rawKey) }
          }
        }
      : {};

    const response = await axios.post(
      `https://api.notion.com/v1/databases/${notionMemoryDBId}/query`,
      body,
      { headers }
    );

    const memory = response.data.results.map(page => {
      const key = page.properties.Key?.title?.[0]?.plain_text || "(no key)";
      const value = page.properties.Value?.rich_text?.[0]?.plain_text || "";
      return { key, value };
    });

    if (rawKey && memory.length === 0) {
      return res.status(404).json({ error: `Memory key '${rawKey}' not found.` });
    }

    res.json({ success: true, memory: rawKey ? memory[0] : memory });
  } catch (err) {
    console.error("❌ read-memory error:", err.response?.data || err.message);
    res.status(500).json({ error: err.message });
  }
});

// === PATCH /notion/create-memory ===
router.patch("/create-memory", async (req, res) => {
  const { line } = req.body;
  if (!line || !line.includes(":")) return res.status(400).json({ error: "Missing or malformed memory line. Format must be 'key: value'" });

  try {
    const [keyPart, ...rest] = line.split(":");
    const key = normalizeKey(keyPart);
    const value = rest.join(":").trim();

    const response = await axios.post("https://api.notion.com/v1/pages", {
      parent: { database_id: notionMemoryDBId },
      properties: {
        Key: { title: [{ text: { content: key } }] },
        Value: { rich_text: [{ text: { content: value } }] },
        LastUpdated: { date: { start: new Date().toISOString() } }
      }
    }, { headers });

    res.json({ success: true, pageId: response.data.id });
  } catch (err) {
    console.error("❌ create-memory error:", err.response?.data || err.message);
    res.status(500).json({ error: err.message });
  }
});

// === PATCH /notion/update-memory ===
router.patch("/update-memory", async (req, res) => {
  const { key, value } = req.body;
  if (!key || !value) return res.status(400).json({ error: "Missing key or value." });

  try {
    const decodedKey = normalizeKey(key);

    const query = await axios.post(`https://api.notion.com/v1/databases/${notionMemoryDBId}/query`, {
      filter: { property: "Key", title: { equals: decodedKey } }
    }, { headers });

    const pageId = query.data.results[0]?.id;
    if (!pageId) return res.status(404).json({ error: `No entry found for key '${key}'` });

    await axios.patch(`https://api.notion.com/v1/pages/${pageId}`, {
      properties: {
        Value: { rich_text: [{ text: { content: value } }] },
        LastUpdated: { date: { start: new Date().toISOString() } }
      }
    }, { headers });

    res.json({ success: true, message: `Memory updated for key '${key}'` });
  } catch (err) {
    console.error("❌ update-memory error:", err.response?.data || err.message);
    res.status(500).json({ error: err.message });
  }
});

// === DELETE /notion/delete-memory ===
router.delete("/delete-memory", async (req, res) => {
  const { key } = req.body;
  if (!key) return res.status(400).json({ error: "Missing key." });

  try {
    const decodedKey = normalizeKey(key);

    const query = await axios.post(`https://api.notion.com/v1/databases/${notionMemoryDBId}/query`, {
      filter: { property: "Key", title: { equals: decodedKey } }
    }, { headers });

    const pageId = query.data.results[0]?.id;
    if (!pageId) return res.status(404).json({ error: `No entry found for key '${key}'` });

    await axios.patch(`https://api.notion.com/v1/pages/${pageId}`, { archived: true }, { headers });

    res.json({ success: true, message: `Memory '${key}' deleted.` });
  } catch (err) {
    console.error("❌ delete-memory error:", err.response?.data || err.message);
    res.status(500).json({ error: err.message });
  }
});

module.exports = router;

