    res.json({ success: true, pageId });
  } catch (error) {
    console.error("❌ append-to-page error:", error.response?.data || error.message);
    res.status(500).json({ error: error.response?.data || error.message });
  }
});

// 4=== Update Page by ID ===
router.patch("/update-page", async (req, res) => {
  const { pageId, content } = req.body;

  if (!pageId || !content) {
    return res.status(400).json({ error: "Missing pageId or content." });
  }

  try {
    const block = {
      object: "block",
      type: "paragraph",
      paragraph: {
        rich_text: [
          {
            type: "text",
            text: { content }
          }
        ]
      }
    };

    const response = await axios.patch(
      `https://api.notion.com/v1/blocks/${pageId}/children`,
      { children: [block] },
      { headers }
    );

    res.json({ success: true, updated: true, pageId });
  } catch (error) {
    console.error("❌ update-page error:", error.response?.data || error.message);
    res.status(500).json({ error: error.response?.data || error.message });
  }
