  const { pageId, content } = req.body;

  if (!pageId || !content) {
    return res.status(400).json({ error: "Missing pageId or content." });
  }

  try {
    await apiCallWithRetry(() => 
      notionApi.patch(`/blocks/${pageId}/children`, {
        children: [createParagraphBlock(content)]
      })
    );

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ success: true, updated: true, pageId });
  } catch (error) {
    handleApiError(res, error, "update-page");
  }
});

// === Query Database ===
router.get("/query-database", async (req, res) => {
  const databaseId = notionDatabaseId;
  const { limit = 100 } = req.query;

  if (!databaseId) {
    return res.status(400).json({ error: "Missing NOTION_DATABASE_ID in secrets." });
  }

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${databaseId}/query`, {
        page_size: parseInt(limit)
      })
    );

    const rows = await Promise.all(response.data.results.map(async (item) => {
      const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

      return {
        title,
        id: item.id,
        type: item.object,
        parent: item.parent?.database_id || null,
        url: item.url || null
      };
    }));

    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    handleApiError(res, error, "query-database");
  }
});

// === Create a Standalone Page ===
router.post("/create-standalone-page", async (req, res) => {
  const { title, content } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Missing title." });
  }

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { type: "page_id", page_id: notionParentPageId },
        properties: {
          title: [
            {
              type: "text",
              text: { content: title }
            }
          ]
        },
        children: [
          createHeadingBlock(title),
          content ? createParagraphBlock(content) : null
        ].filter(Boolean) // Remove null entries
      })
    );

    // Invalidate cache
    cache.clear();

    res.json({ success: true, pageId: response.data.id });
  } catch (error) {
    handleApiError(res, error, "create-standalone-page");
  }
});

// === Archive Page ===
router.delete("/page/:id", async (req, res) => {
  const pageId = req.params.id;

  try {
    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        archived: true
      })
    );

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ success: true, archived: true });
  } catch (error) {
    handleApiError(res, error, "archive-page");
  }
});

// === Memory Management Routes ===

// === GET /notion/read-memory ===
router.get("/read-memory", async (req, res) => {
  try {
    const rawKey = req.query.key;
    const body = rawKey
      ? {
          filter: {
            property: "Key",
            title: { equals: normalizeKey(rawKey) }
          }
        }
      : {};

    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, body)
    );

    const memory = response.data.results.map(page => {
      const key = page.properties.Key?.title?.[0]?.plain_text || "(no key)";
      const value = page.properties.Value?.rich_text?.[0]?.plain_text || "";
      return { key, value };
    });

    if (rawKey && memory.length === 0) {
      return res.status(404).json({ error: `Memory key '${rawKey}' not found.` });
    }

    res.json({ success: true, memory: rawKey ? memory[0] : memory });
  } catch (err) {
    handleApiError(res, err, "read-memory");
  }
});

// === PATCH /notion/create-memory ===
router.patch("/create-memory", async (req, res) => {
  const { line } = req.body;
  if (!line || !line.includes(":")) {
    return res.status(400).json({ 
      error: "Missing or malformed memory line. Format must be 'key: value'" 
    });
  }

  try {
    const [keyPart, ...rest] = line.split(":");
    const key = normalizeKey(keyPart);
    const value = rest.join(":").trim();

    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { database_id: notionMemoryDBId },
        properties: {
          Key: { title: [{ text: { content: key } }] },
          Value: { rich_text: [{ text: { content: value } }] },
          LastUpdated: { date: { start: new Date().toISOString() } }
        }
      })
    );

    res.json({ success: true, pageId: response.data.id });
  } catch (err) {
    handleApiError(res, err, "create-memory");
  }
});

// === PATCH /notion/update-memory ===
router.patch("/update-memory", async (req, res) => {
  const { key, value } = req.body;
  if (!key || !value) {
    return res.status(400).json({ error: "Missing key or value." });
  }

  try {
    const decodedKey = normalizeKey(key);

    const query = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, {
        filter: { property: "Key", title: { equals: decodedKey } }
      })
    );

    const pageId = query.data.results[0]?.id;
    if (!pageId) {
      return res.status(404).json({ error: `No entry found for key '${key}'` });
    }

    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        properties: {
          Value: { rich_text: [{ text: { content: value } }] },
          LastUpdated: { date: { start: new Date().toISOString() } }
        }
      })
    );

    res.json({ success: true, message: `Memory updated for key '${key}'` });
  } catch (err) {
    handleApiError(res, err, "update-memory");
  }
});

// === DELETE /notion/delete-memory ===
router.delete("/delete-memory", async (req, res) => {
  const { key } = req.body;
  if (!key) {
    return res.status(400).json({ error: "Missing key." });
  }

  try {
    const decodedKey = normalizeKey(key);

    const query = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, {
        filter: { property: "Key", title: { equals: decodedKey } }
      })
    );

    const pageId = query.data.results[0]?.id;
    if (!pageId) {
      return res.status(404).json({ error: `No entry found for key '${key}'` });
    }

    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, { archived: true })
    );

    res.json({ success: true, message: `Memory '${key}' deleted.` });
  } catch (err) {
    handleApiError(res, err, "delete-memory");
  }
});

// === Health Check Route ===
router.get("/health", async (req, res) => {
  try {
    // Check if Notion API is accessible
    await notionApi.get('/users/me');
    res.json({ status: 'healthy', message: 'Notion integration is working properly' });
  } catch (error) {
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to connect to Notion API',
      error: error.message
    });
  }
});

module.exports = router;
