    const headingBlock = blocks.find((block) =>
      ["heading_1", "heading_2", "heading_3", "paragraph"].includes(block.type)
    );

    if (headingBlock) {
      const title = headingBlock[headingBlock.type]?.rich_text?.map(r => r.text?.content).join("").trim();
      console.log(`✅ Fallback block title for ${pageId}: ${title}`);
      return title || null;
    }

    console.log(`⚠️ No usable title found for ${pageId}`);
    return null;
  } catch (err) {
    console.error(`❌ Title extraction failed for ${pageId}:`, err.message);
    return null;
  }
}

