<antArtifact identifier="notion-cache-improvements" title="Improved Cache Implementation" type="application/vnd.ant.code" language="javascript">
// notion-cache.js
// Enhanced cache with better memory management

class NotionCache {
  constructor(options = {}) {
    this.stores = {
      pages: new Map(),
      titles: new Map()
    };

    this.ttl = options.ttl || CONFIG.CACHE_TTL;
    this.maxItems = options.maxItems || CONFIG.CACHE_MAX_ITEMS;
    this.maxValueSize = options.maxValueSize || 1024 * 1024; // 1MB default
    this.cleanupInterval = options.cleanupInterval || CONFIG.CACHE_CLEANUP_INTERVAL;
    this.lastCleanup = Date.now();

    // Add metrics
    this.metrics = {
      hits: 0,
      misses: 0,
      evictions: 0,
      sizeEvictions: 0
    };

    // Start periodic cleanup
    if (options.autoCleanup !== false) {
      this.startPeriodicCleanup();
    }
  }

  // Start the cleanup interval
  startPeriodicCleanup() {
    setInterval(() => this.cleanup(), this.cleanupInterval);
  }

  // Get the size of a value in bytes (approximate)
  getValueSize(value) {
    try {
      return JSON.stringify(value).length;
    } catch (e) {
      return 0;
    }
  }

  // Set a value in the cache with LRU eviction
  set(key, value, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    // Check value size
    const valueSize = this.getValueSize(value);
    if (valueSize > this.maxValueSize) {
      console.warn(`Cache value for key ${key} too large (${valueSize} bytes), skipping cache`);
      this.metrics.sizeEvictions++;
      return;
    }

    // Check if at max capacity and evict LRU items if needed
    if (this.stores[type].size >= this.maxItems) {
      // Sort by last accessed time
      const entries = Array.from(this.stores[type].entries())
        .sort((a, b) => a[1].lastAccessed - b[1].lastAccessed);

      // Remove oldest accessed entries
      const toRemove = entries.slice(0, Math.ceil(this.maxItems * 0.2)); // Remove 20%
      for (const [k] of toRemove) {
        this.stores[type].delete(k);
        this.metrics.evictions++;
      }

      console.log(`🧹 Cache eviction: removed ${toRemove.length} LRU items from ${type} store`);
    }

    // Add new item with access tracking
    this.stores[type].set(key, {
      value,
      timestamp: Date.now(),
      lastAccessed: Date.now(),
      size: valueSize
    });

    // Run cleanup if it's been more than the cleanup interval
    if (Date.now() - this.lastCleanup > this.cleanupInterval) {
      this.cleanup();
    }
  }

  // Get a value with access time tracking
  get(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      this.metrics.misses++;
      return null;
    }

    const item = this.stores[type].get(key);
    if (!item) {
      this.metrics.misses++;
      return null;
    }

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this.stores[type].delete(key);
      this.metrics.misses++;
      return null;
    }

    // Update last accessed time
    item.lastAccessed = Date.now();
    this.metrics.hits++;

    return item.value;
  }

  // The rest of the methods remain similar with metrics added

  // Get cache metrics
  getMetrics() {
    const totalItems = Object.values(this.stores).reduce(
      (sum, store) => sum + store.size, 0
    );

    const totalSize = Object.values(this.stores).reduce(
      (sum, store) => {
        return sum + Array.from(store.values()).reduce(
          (storeSum, item) => storeSum + (item.size || 0), 0
        );
      }, 0
    );

    return {
      ...this.metrics,
      totalItems,
      totalSize,
      hitRatio: this.metrics.hits / (this.metrics.hits + this.metrics.misses || 1),
      stores: Object.entries(this.stores).map(([type, store]) => ({
        type,
        size: store.size
      }))
    };
  }
}

module.exports = NotionCache;
</antArtifact>

