/**
 * Creates a standardized Notion page with proper content and formatting
 * @param {string} title - The page title
 * @param {string} content - The page content
 * @param {string} parentId - The parent page/database ID
 * @param {Object} options - Additional options
 * @returns {Promise<Object>} - The API response with page details
 */
async function createNotionPage(title, content, parentId, options = {}) {
  const sanitizedTitle = sanitizeInput(title);
  const sanitizedContent = sanitizeInput(content);

  if (!sanitizedTitle) {
    throw new Error("Title cannot be empty after sanitization.");
  }

  const childrenBlocks = [createHeadingBlock(sanitizedTitle)];

  // Add metadata if provided
  if (options.metadata) {
    childrenBlocks.push(
      createParagraphBlock(`${options.metadata} - Created ${new Date().toLocaleString()}`)
    );
  }

  // Add content section
  if (options.useContentHeading !== false) {
    childrenBlocks.push(createHeadingBlock("Content", 2));
  }

  // Handle content blocks (which might be an array after splitting long content)
  if (sanitizedContent) {
    const contentBlocks = createParagraphBlock(sanitizedContent);
    if (Array.isArray(contentBlocks)) {
      childrenBlocks.push(...contentBlocks);
    } else {
      childrenBlocks.push(contentBlocks);
    }
  }

  return await apiCallWithRetry(() => 
    notionApi.post('/pages', {
      parent: { 
        type: parentId.includes("-") ? "page_id" : "database_id", 
        [parentId.includes("-") ? "page_id" : "database_id"]: parentId 
      },
      properties: {
        title: [
          {
            type: "text",
            text: { content: sanitizedTitle }
          }
        ]
      },
      children: childrenBlocks
    })
  );
}

/**
 * Centralized API wrapper for Notion calls
 * @param {string} method - HTTP method
 * @param {string} endpoint - API endpoint
 * @param {Object} data - Request payload
 * @param {Object} options - Additional options
 * @returns {Promise<Object>} - API response
 */
async function notionApiCall(method, endpoint, data = null, options = {}) {
  const finalEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;

  return await apiCallWithRetry(() => {
    if (method.toLowerCase() === 'get') {
      return notionApi.get(finalEndpoint, { params: data });
    } else {
      return notionApi[method.toLowerCase()](finalEndpoint, data);
    }
  }, options);
}

module.exports = {
  createNotionPage,
  notionApiCall
};
