<antArtifact identifier="notion-security-improvements" title="Security and Error Handling Improvements" type="application/vnd.ant.code" language="javascript">
// === Enhanced Input Sanitization ===
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;

  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }

  // More thorough sanitization
  return input
    .trim()
    // Prevent script injection
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    // Sanitize potential markdown injection vectors
    .replace(/javascript:/gi, 'blocked:')
    // Additional sanitization as needed
    .replace(/data:/gi, 'blocked:');
}

// === Improved Error Handling with Better Context ===
const handleApiError = (res, error, context) => {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};

  // Add request timestamp
  const timestamp = new Date().toISOString();

  // Generate a unique error ID for tracking
  const errorId = `err_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;

  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};

    // Add more context for rate limiting
    if (statusCode === 429) {
      errorDetails.rateLimiting = {
        retryAfter: error.response.headers['retry-after'],
        remainingRequests: error.response.headers['x-ratelimit-remaining']
      };
    }
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { 
      errorCode: 'NO_RESPONSE', 
      message: error.message,
      timeout: error.code === 'ETIMEDOUT'
    };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }

  // Add request context to the error
  errorDetails.context = context;
  errorDetails.timestamp = timestamp;
  errorDetails.errorId = errorId;

  // Log the full error with stack trace
  console.error(`❌ [${errorId}] ${context} error:`, errorMessage, error.stack || '(No stack trace)');
  console.error(`Context details:`, errorDetails);

  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context,
    errorId
  });

  // Additional logging for critical errors
  if (statusCode >= 500) {
    // Here you could add additional error reporting logic
    // e.g., send to an error tracking service
  }
};

// === Better RegEx security ===
// Replace the unsafe regex in createVersionedPage with:
function escapeRegExp(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Then use:
const safeTitle = escapeRegExp(baseTitle);
const titleRegex = new RegExp(`^${safeTitle}\\s+(\\d+)$`);

// Add timeout to Promise.race
async function apiCallWithTimeout(promise, timeoutMs) {
  const timeoutPromise = new Promise((_, reject) => {
    setTimeout(() => reject(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);
  });

  return Promise.race([promise, timeoutPromise]);
}
</antArtifact>

