  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let pageCount = 0;

  while (hasMore) {
    const queryParams = { ...params, page_size: pageSize };
    if (startCursor) {
      queryParams.start_cursor = startCursor;
    }

    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    });

    const responseResults = response.data.results || [];
    results = results.concat(responseResults);
    hasMore = response.data.has_more;
    startCursor = response.data.next_cursor;
    pageCount++;

    console.log(`📊 Fetched page ${pageCount} with ${responseResults.length} items from ${endpoint}`);

    // Safety check to prevent excessive pagination
    if (results.length >= maxItems) {
      console.warn(`⚠️ Pagination limit reached (${maxItems} items)`);
      break;
    }

    // Prevent infinite loops
    if (pageCount > 50) {
      console.error(`❌ Too many pages fetched (${pageCount}). Possible API issue.`);
      break;
    }
  }

  return results;
}
