const { CONFIG } = require("../config/notion-config");

// === Enhanced Caching Setup ===
class NotionCache {
  constructor(options = {}) {
    this.stores = {
      pages: new Map(),
      titles: new Map()
    };

    this.ttl = options.ttl || CONFIG.CACHE_TTL;
    this.maxItems = options.maxItems || CONFIG.CACHE_MAX_ITEMS;
    this.cleanupInterval = options.cleanupInterval || CONFIG.CACHE_CLEANUP_INTERVAL;
    this.lastCleanup = Date.now();
    this.lastAccess = {}; // Track LRU information

    // Start periodic cleanup
    if (options.autoCleanup !== false) {
      this.startPeriodicCleanup();
    }
  }

  startPeriodicCleanup() {
    setInterval(() => this.cleanup(), this.cleanupInterval);
  }

  set(key, value, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    // Update or add LRU tracking
    this.lastAccess[`${type}:${key}`] = Date.now();

    // Check if at max capacity and evict oldest item if needed
    if (this.stores[type].size >= this.maxItems) {
      // Use LRU (Least Recently Used) for eviction
      let lruKey = null;
      let lruAccessTime = Infinity;

      for (const [k, _] of this.stores[type].entries()) {
        const accessKey = `${type}:${k}`;
        const lastAccessTime = this.lastAccess[accessKey] || 0;

        if (lastAccessTime < lruAccessTime) {
          lruAccessTime = lastAccessTime;
          lruKey = k;
        }
      }

      if (lruKey) {
        this.stores[type].delete(lruKey);
        delete this.lastAccess[`${type}:${lruKey}`];
        console.log(`🧹 Cache eviction: removed LRU item '${lruKey}' from ${type} store`);
      }
    }

    // Add new item
    this.stores[type].set(key, {
      value,
      timestamp: Date.now()
    });

    // Run cleanup if it's been more than the cleanup interval
    if (Date.now() - this.lastCleanup > this.cleanupInterval) {
      this.cleanup();
    }
  }

  get(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return null;
    }

    const item = this.stores[type].get(key);
    if (!item) return null;

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this.stores[type].delete(key);
      delete this.lastAccess[`${type}:${key}`];
      return null;
    }

    // Update access time for LRU tracking
    this.lastAccess[`${type}:${key}`] = Date.now();

    return item.value;
  }

  invalidate(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    this.stores[type].delete(key);
    delete this.lastAccess[`${type}:${key}`];
  }

  clear() {
    for (const storeType in this.stores) {
      this.stores[storeType].clear();
    }
    this.lastAccess = {};
    this.lastCleanup = Date.now();
    console.log('🧹 Cache cleared completely');
  }

  cleanup() {
    const now = Date.now();
    this.lastCleanup = now;
    let totalRemoved = 0;

    for (const [storeType, store] of Object.entries(this.stores)) {
      let storeRemoved = 0;

      for (const [key, item] of store.entries()) {
        if (now - item.timestamp > this.ttl) {
          store.delete(key);
          delete this.lastAccess[`${storeType}:${key}`];
          storeRemoved++;
        }
      }

      totalRemoved += storeRemoved;
      if (storeRemoved > 0) {
        console.log(`🧹 Cache cleanup: removed ${storeRemoved} items from ${storeType} store`);
      }
    }

    if (totalRemoved > 0) {
      const stats = Object.entries(this.stores).map(([type, store]) => `${type}: ${store.size}`).join(', ');
      console.log(`🧹 Cache cleanup completed. Removed ${totalRemoved} items. Current sizes: ${stats}`);
    }
  }

  getStats() {
    const stats = {};
    let totalMemoryUsage = 0;

    for (const [type, store] of Object.entries(this.stores)) {
      stats[type] = {
        size: store.size,
        oldestItem: null,
        newestItem: null
      };

      // Calculate oldest and newest items
      let oldestTime = Infinity;
      let newestTime = 0;

      for (const [key, item] of store.entries()) {
        if (item.timestamp < oldestTime) {
          oldestTime = item.timestamp;
          stats[type].oldestItem = {
            key,
            age: Math.round((Date.now() - item.timestamp) / 1000) + 's'
          };
        }

        if (item.timestamp > newestTime) {
          newestTime = item.timestamp;
          stats[type].newestItem = {
            key,
            age: Math.round((Date.now() - item.timestamp) / 1000) + 's'
          };
        }

        // Rough estimate of memory usage
        try {
          totalMemoryUsage += JSON.stringify(item.value).length * 2; // Rough estimate: 2 bytes per character
        } catch (e) {
          // Ignore stringify errors
        }
      }
    }

    stats.memory = {
      estimated: `~${Math.round(totalMemoryUsage / 1024)} KB`,
      lastCleanup: new Date(this.lastCleanup).toISOString()
    };

    return stats;
  }
}

// Create a singleton cache instance
const cache = new NotionCache();

module.exports = {
  cache,
  NotionCache
