    const pages = await Promise.all(searchResponse.data.results.map(async (page) => {
      try {
        const extractedTitle = await extractPageTitle(page);
        return {
          page,
          title: extractedTitle
        };
      } catch (err) {
        console.error(`Error extracting title for page ${page.id}:`, err.message);
        return {
          page,
          title: `Untitled (${page.id.substring(0, 8)})`
        };
      }
    }));

    // Find exact match or closest match
    const exactMatch = pages.find(item => 
      item.title && item.title.toLowerCase() === normalizedInput
    );

    const match = exactMatch || null;

    // Cache the result
    if (match) {
      cache.set(cacheKey, match);
    }

    return match;
  } catch (error) {
    console.error(`❌ Find page error for "${title}":`, error.message);
    return null;
  }
}

// === Utility: Enhanced child pages extraction ===
async function extractChildPages(pageId, pages = [], visited = new Set(), depth = 0, maxDepth = 3) {
  // Guard against invalid pageId or excessive recursion
  if (!pageId || visited.has(pageId) || depth > maxDepth) {
    return pages;
  }

  // Protect against infinite recursion
  visited.add(pageId);

  // Track recursion depth for debugging
  const indentation = "  ".repeat(depth);
  console.log(`${indentation}🔍 Exploring page ${pageId} (depth: ${depth}/${maxDepth})`);

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    );

    const blocks = response.data.results;

    const blockCount = blocks.length;
    console.log(`${indentation}🧱 Found ${blockCount} blocks in page ${pageId}`);

    // Process child pages specifically
    const childPagePromises = blocks
      .filter(block => block.type === "child_page")
      .map(async (block) => {
        const childId = block.id;

        // Skip if we already added this page
        if (pages.some(p => p.id === childId)) {
          console.log(`${indentation}⚠️ Duplicate page detected: ${childId}`);
          return null;
        }

        let childTitle = block.child_page?.title;

        // If no title in the initial response, try to extract it
        if (!childTitle || childTitle === "(no title)") {
          try {
            const pageInfo = await apiCallWithRetry(() => 
              notionApi.get(`/pages/${childId}`)
            );
            childTitle = await extractPageTitle(pageInfo.data) || childTitle || "(no title)";
          } catch (err) {
            console.error(`${indentation}❌ Failed to fetch child page info for ${childId}:`, err.message);
            childTitle = `Untitled (${childId.substring(0, 8)})`;
          }
        }

        console.log(`${indentation}📄 Found child page: ${childTitle} (ID: ${childId})`);

        return {
          id: childId,
          title: childTitle,
          parent: pageId,
          type: "page"
        };
      });

    // Wait for all promises to resolve and filter out nulls
    const childPages = (await Promise.all(childPagePromises)).filter(Boolean);

    // Add the child pages to our results
    for (const childPage of childPages) {
      pages.push(childPage);
    }

    // Process nested pages with controlled concurrency (max 3 concurrent requests)
    if (depth < maxDepth) {
      const batchSize = 3;
      for (let i = 0; i < childPages.length; i += batchSize) {
        const batch = childPages.slice(i, i + batchSize);
        await Promise.all(
          batch.map(child => 
            extractChildPages(child.id, pages, visited, depth + 1, maxDepth)
          )
        );
      }
    }

    return pages;
  } catch (err) {
    console.error(`${indentation}❌ Failed to fetch children for ${pageId}:`, err.message);
    return pages;
  }
}

// === Enhanced Pagination helper ===
async function paginatedRequest(endpoint, params = {}, options = {}) {
  const pageSize = options.pageSize || CONFIG.DEFAULT_PAGE_SIZE;
  const maxItems = options.maxItems || CONFIG.MAX_ITEMS_PER_PAGE;
  const concurrentRequests = options.concurrentRequests || 1;

  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let pageCount = 0;

  const makeRequest = async (cursor) => {
    const queryParams = { ...params, page_size: pageSize };
    if (cursor) {
      queryParams.start_cursor = cursor;
    }

    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    });

    return response.data;
  };

  // First request to get initial batch and pagination info
  try {
    const firstBatch = await makeRequest(undefined);
    results = [...firstBatch.results];
    hasMore = firstBatch.has_more;
    startCursor = firstBatch.next_cursor;
    pageCount++;

    console.log(`📊 Fetched page ${pageCount} with ${results.length} items from ${endpoint}`);

    // If we need more pages and haven't hit limits
    const cursors = [];
    while (hasMore && results.length < maxItems && pageCount < 50) {
      cursors.push(startCursor);

      // Process in batches of concurrent requests
      if (cursors.length >= concurrentRequests || !hasMore) {
        const batchResults = await Promise.all(
          cursors.map(cursor => makeRequest(cursor))
        );

        for (const data of batchResults) {
          results = results.concat(data.results || []);
          hasMore = data.has_more;
          startCursor = data.next_cursor;
          pageCount++;

          console.log(`📊 Fetched page ${pageCount} with ${data.results.length} items from ${endpoint}`);

          if (results.length >= maxItems) {
            console.warn(`⚠️ Pagination limit reached (${maxItems} items)`);
            hasMore = false;
            break;
          }

          if (pageCount >= 50) {
            console.error(`❌ Too many pages fetched (${pageCount}). Possible API issue.`);
            hasMore = false;
            break;
          }

          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }

        cursors.length = 0;
      }
    }

    return results;
  } catch (error) {
    console.error(`❌ Pagination error for ${endpoint}:`, error.message);
    throw error;
  }
}

// === Normalize keys for memory functions with better error handling ===
function normalizeKey(key) {
  if (!key) return "";

  const sanitizedKey = sanitizeInput(key, "");

  try {
    return decodeURIComponent(sanitizedKey.toLowerCase());
  } catch (e) {
    console.error(`❌ Error decoding URI component: ${key}`, e);
    return sanitizedKey.toLowerCase();
  }
}

