// === Full Notion Integration: Core Routes + Memory Extensions ===
const express = require("express");
const router = express.Router();
const axios = require("axios");

// === Environment Variables Validation ===
const requiredEnvVars = [
  'NOTION_TOKEN', 
  'NOTION_PARENT_PAGE_ID', 
  'NOTION_DATABASE_ID', 
  'GPT_MEMORY'
];

for (const varName of requiredEnvVars) {
  if (!process.env[varName]) {
    console.error(`❌ Missing required environment variable: ${varName}`);
    process.exit(1);
  }
}

const notionToken = process.env.NOTION_TOKEN;
const notionParentPageId = process.env.NOTION_PARENT_PAGE_ID;
const notionDatabaseId = process.env.NOTION_DATABASE_ID;
const notionMemoryDBId = process.env.GPT_MEMORY;

// Configuration
const CONFIG = {
  CACHE_TTL: process.env.CACHE_TTL_MS || 1000 * 60 * 5, // 5 minutes default
  CACHE_CLEANUP_INTERVAL: process.env.CACHE_CLEANUP_INTERVAL_MS || 1000 * 60 * 10, // 10 minutes default
  CACHE_MAX_ITEMS: process.env.CACHE_MAX_ITEMS || 1000, // Maximum items in cache
  API_TIMEOUT: process.env.API_TIMEOUT_MS || 10000, // 10 seconds default
  MAX_CONTENT_LENGTH: 1800, // Maximum content length per block
  MAX_ITEMS_PER_PAGE: process.env.MAX_ITEMS_PER_PAGE || 5000,
  DEFAULT_PAGE_SIZE: process.env.DEFAULT_PAGE_SIZE || 100
};

// === Create Axios Instance with Default Configuration ===
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${notionToken}`,
    "Notion-Version": "2022-06-28",
    "Content-Type": "application/json"
  },
  timeout: CONFIG.API_TIMEOUT
});

// === Enhanced Caching Setup ===
class NotionCache {
  constructor(options = {}) {
    this.stores = {
      pages: new Map(),
      titles: new Map()
    };

    this.ttl = options.ttl || CONFIG.CACHE_TTL;
    this.maxItems = options.maxItems || CONFIG.CACHE_MAX_ITEMS;
    this.cleanupInterval = options.cleanupInterval || CONFIG.CACHE_CLEANUP_INTERVAL;
    this.lastCleanup = Date.now();

    // Start periodic cleanup
    if (options.autoCleanup !== false) {
      this.startPeriodicCleanup();
    }
  }

  startPeriodicCleanup() {
    setInterval(() => this.cleanup(), this.cleanupInterval);
  }

  set(key, value, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    // Check if at max capacity and evict oldest item if needed
    if (this.stores[type].size >= this.maxItems) {
      let oldestKey = null;
      let oldestTime = Infinity;

      for (const [k, item] of this.stores[type].entries()) {
        if (item.timestamp < oldestTime) {
          oldestTime = item.timestamp;
          oldestKey = k;
        }
      }

      if (oldestKey) {
        this.stores[type].delete(oldestKey);
        console.log(`🧹 Cache eviction: removed oldest item from ${type} store`);
      }
    }

    // Add new item
    this.stores[type].set(key, {
      value,
      timestamp: Date.now()
    });

    // Run cleanup if it's been more than the cleanup interval
    if (Date.now() - this.lastCleanup > this.cleanupInterval) {
      this.cleanup();
    }
  }

  get(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return null;
    }

    const item = this.stores[type].get(key);
    if (!item) return null;

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this.stores[type].delete(key);
      return null;
    }

    return item.value;
  }

  invalidate(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    this.stores[type].delete(key);
  }

  clear() {
    for (const storeType in this.stores) {
      this.stores[storeType].clear();
    }
    this.lastCleanup = Date.now();
    console.log('🧹 Cache cleared completely');
  }

  cleanup() {
    const now = Date.now();
    this.lastCleanup = now;
    let totalRemoved = 0;

    for (const [storeType, store] of Object.entries(this.stores)) {
      let storeRemoved = 0;

      for (const [key, item] of store.entries()) {
        if (now - item.timestamp > this.ttl) {
          store.delete(key);
          storeRemoved++;
        }
      }

      totalRemoved += storeRemoved;
      console.log(`🧹 Cache cleanup: removed ${storeRemoved} items from ${storeType} store`);
    }

    const stats = Object.entries(this.stores).map(([type, store]) => `${type}: ${store.size}`).join(', ');
    console.log(`🧹 Cache cleanup completed. Removed ${totalRemoved} items. Current sizes: ${stats}`);
  }

  getStats() {
    const stats = {};
    for (const [type, store] of Object.entries(this.stores)) {
      stats[type] = store.size;
    }
    return stats;
  }
}

const cache = new NotionCache();

// === Improved Error Handling Helper ===
const handleApiError = (res, error, context) => {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};

  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { errorCode: 'NO_RESPONSE', message: error.message };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }

  // Add request context to the error
  errorDetails.context = context;

  console.error(`❌ ${context} error:`, errorMessage, errorDetails);

  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context
  });
};

// === Enhanced Retry Logic with Jitter ===
async function apiCallWithRetry(fn, options = {}) {
  const maxRetries = options.maxRetries || 3;
  const baseDelay = options.baseDelay || 1000; // 1 second
  const maxDelay = options.maxDelay || 10000; // 10 seconds
  const timeoutMs = options.timeout || CONFIG.API_TIMEOUT;

  let retries = 0;

  while (true) {
    try {
      // Add timeout handling
      const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => reject(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);
      });

      const resultPromise = fn();

      // Race between the API call and the timeout
      return await Promise.race([resultPromise, timeoutPromise]);
    } catch (error) {
      const isRetryable = 
        error.response?.status === 429 || // Rate limited
        error.response?.status === 503 || // Service unavailable
        error.response?.status >= 500 ||  // Server errors
        error.code === 'ECONNRESET' ||    // Connection reset
        error.code === 'ETIMEDOUT' ||     // Connection timeout
        error.message.includes('timeout'); // Generic timeout error

      if (isRetryable && retries < maxRetries) {
        // Calculate delay with exponential backoff and jitter
        const exponentialDelay = Math.min(
          maxDelay,
          baseDelay * Math.pow(2, retries)
        );
        // Add jitter: random value between 0 and 1 * 0.5 * calculated delay
        const jitter = Math.random() * 0.5 * exponentialDelay;
        const delay = exponentialDelay + jitter;

        console.log(`API call failed with ${error.response?.status || error.code || 'unknown error'}, retrying in ${Math.round(delay)}ms... (${retries + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        // Either not retryable or max retries exceeded
        if (retries >= maxRetries) {
          console.error(`❌ Max retries (${maxRetries}) exceeded for API call. Last error:`, error.message);
        }
        throw error;
      }
    }
  }
}

// === Utility: Safely sanitize input strings ===
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;
  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }
  return input.trim();
}

// === Block Creation Helpers ===
function createParagraphBlock(content) {
  // Validate and sanitize content
  content = sanitizeInput(content, "");
  if (!content) return createSingleParagraphBlock("");

  // Split content into manageable chunks if too long
  if (content.length > CONFIG.MAX_CONTENT_LENGTH) {
    const chunks = [];
    const maxLength = CONFIG.MAX_CONTENT_LENGTH;

    // First try to split by sentences for more natural breaks
    const sentences = content.split(/(?<=[.!?])\s+/);
    let currentChunk = "";

    for (const sentence of sentences) {
      // If adding this sentence exceeds max length, create a new chunk
      if ((currentChunk + (currentChunk ? " " : "") + sentence).length > maxLength) {
        if (currentChunk) {
          chunks.push(createSingleParagraphBlock(currentChunk));
          currentChunk = "";
        }

        // Handle case where a single sentence is too long
        if (sentence.length > maxLength) {
          // Split by words for very long sentences
          const words = sentence.split(/\s+/);
          let wordChunk = "";

          for (const word of words) {
            if ((wordChunk + (wordChunk ? " " : "") + word).length > maxLength) {
              if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
              // If a single word is too long (rare), split it
              if (word.length > maxLength) {
                for (let i = 0; i < word.length; i += maxLength) {
                  chunks.push(createSingleParagraphBlock(word.substring(i, i + maxLength)));
                }
                wordChunk = "";
              } else {
                wordChunk = word;
              }
            } else {
              wordChunk += (wordChunk ? " " : "") + word;
            }
          }

          if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
        } else {
          currentChunk = sentence;
        }
      } else {
        currentChunk += (currentChunk ? " " : "") + sentence;
      }
    }

    if (currentChunk) chunks.push(createSingleParagraphBlock(currentChunk));
    return chunks;
  }

  return createSingleParagraphBlock(content);
}

function createSingleParagraphBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

function createHeadingBlock(content, level = 1) {
  content = sanitizeInput(content, "Untitled");

  // Validate level is 1, 2, or 3
  if (![1, 2, 3].includes(level)) {
    console.warn(`Invalid heading level: ${level}, defaulting to 1`);
    level = 1;
  }

  const headingType = `heading_${level}`;
  return {
    object: "block",
    type: headingType,
    [headingType]: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

