/**
 * Notion Cache Module
 * 
 * Provides an enhanced caching implementation for Notion API responses with:
 * - Time-to-live (TTL) management
 * - Automated cleanup of expired entries
 * - Multiple cache stores for different data types
 * - Eviction policies for memory management
 */

const { CONFIG } = require('../../config');

/**
 * Enhanced Caching Implementation for Notion API
 * Provides efficient caching with TTL, auto cleanup, and multiple stores
 */
class NotionCache {
  /**
   * Creates a new NotionCache instance
   * @param {Object} options - Cache configuration options
   * @param {number} [options.ttl] - Cache time-to-live in milliseconds
   * @param {number} [options.maxItems] - Maximum items to store per cache store
   * @param {number} [options.cleanupInterval] - Interval for cleanup in milliseconds
   * @param {boolean} [options.autoCleanup] - Whether to automatically clean up expired items
   */
  constructor(options = {}) {
    this.stores = {
      pages: new Map(),
      titles: new Map()
    };

    this.ttl = options.ttl || CONFIG.CACHE_TTL;
    this.maxItems = options.maxItems || CONFIG.CACHE_MAX_ITEMS;
    this.cleanupInterval = options.cleanupInterval || CONFIG.CACHE_CLEANUP_INTERVAL;
    this.lastCleanup = Date.now();

    // Start periodic cleanup
    if (options.autoCleanup !== false) {
      this.startPeriodicCleanup();
    }
  }

  /**
   * Starts periodic cleanup of expired cache items
   */
  startPeriodicCleanup() {
    setInterval(() => this.cleanup(), this.cleanupInterval);
  }

  /**
   * Adds or updates an item in the cache
   * @param {string} key - The cache key
   * @param {*} value - The value to cache
   * @param {string} [type='pages'] - The cache store to use
   */
  set(key, value, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    // Check if at max capacity and evict oldest item if needed
    if (this.stores[type].size >= this.maxItems) {
      let oldestKey = null;
      let oldestTime = Infinity;

      for (const [k, item] of this.stores[type].entries()) {
        if (item.timestamp < oldestTime) {
          oldestTime = item.timestamp;
          oldestKey = k;
        }
      }

      if (oldestKey) {
        this.stores[type].delete(oldestKey);
        console.log(`🧹 Cache eviction: removed oldest item from ${type} store`);
      }
    }

    // Add new item
    this.stores[type].set(key, {
      value,
      timestamp: Date.now()
    });

    // Run cleanup if it's been more than the cleanup interval
    if (Date.now() - this.lastCleanup > this.cleanupInterval) {
      this.cleanup();
    }
  }

  /**
   * Retrieves an item from the cache if not expired
   * @param {string} key - The cache key
   * @param {string} [type='pages'] - The cache store to use
   * @returns {*|null} The cached value or null if not found or expired
   */
  get(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return null;
    }

    const item = this.stores[type].get(key);
    if (!item) return null;

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this.stores[type].delete(key);
      return null;
    }

    return item.value;
  }

  /**
   * Removes a specific item from the cache
   * @param {string} key - The cache key to invalidate
   * @param {string} [type='pages'] - The cache store to use
   */
  invalidate(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    this.stores[type].delete(key);
  }

  /**
   * Clears all items from all cache stores
   */
  clear() {
    for (const storeType in this.stores) {
      this.stores[storeType].clear();
    }
    this.lastCleanup = Date.now();
    console.log('🧹 Cache cleared completely');
  }

  /**
   * Removes all expired items from all cache stores
   */
  cleanup() {
    const now = Date.now();
    this.lastCleanup = now;
    let totalRemoved = 0;

    for (const [storeType, store] of Object.entries(this.stores)) {
      let storeRemoved = 0;

      for (const [key, item] of store.entries()) {
        if (now - item.timestamp > this.ttl) {
          store.delete(key);
          storeRemoved++;
        }
      }

      totalRemoved += storeRemoved;
      console.log(`🧹 Cache cleanup: removed ${storeRemoved} items from ${storeType} store`);
    }

    const stats = Object.entries(this.stores).map(([type, store]) => `${type}: ${store.size}`).join(', ');
    console.log(`🧹 Cache cleanup completed. Removed ${totalRemoved} items. Current sizes: ${stats}`);
  }

  /**
   * Returns statistics about the cache stores
   * @returns {Object} Object containing the size of each cache store
   */
  getStats() {
    const stats = {};
    for (const [type, store] of Object.entries(this.stores)) {
      stats[type] = store.size;
    }
    return stats;
  }
}

// Create and export a cache instance with default configuration
const cache = new NotionCache();

module.exports = {
  NotionCache,
  cache
};

/**
 * Notion Block Utilities
 * 
 * This module provides helper functions for creating and managing Notion blocks,
 * including handling of text content with proper splitting for Notion API limitations.
 */

const { CONFIG } = require('../../config');
const { sanitizeInput } = require('../../api-utils');

/**
 * Creates a paragraph block or array of paragraph blocks for content
 * Handles automatic splitting of content that exceeds Notion's maximum length
 * 
 * @param {string} content - The text content for the paragraph
 * @returns {Object|Array} - A single paragraph block or array of blocks if content exceeds max length
 */
function createParagraphBlock(content) {
  // Validate and sanitize content
  content = sanitizeInput(content, "");
  if (!content) return createSingleParagraphBlock("");

  // Split content into manageable chunks if too long
  if (content.length > CONFIG.MAX_CONTENT_LENGTH) {
    const chunks = [];
    const maxLength = CONFIG.MAX_CONTENT_LENGTH;

    // First try to split by sentences for more natural breaks
    const sentences = content.split(/(?<=[.!?])\s+/);
    let currentChunk = "";

    for (const sentence of sentences) {
      // If adding this sentence exceeds max length, create a new chunk
      if ((currentChunk + (currentChunk ? " " : "") + sentence).length > maxLength) {
        if (currentChunk) {
          chunks.push(createSingleParagraphBlock(currentChunk));
          currentChunk = "";
        }

        // Handle case where a single sentence is too long
        if (sentence.length > maxLength) {
          // Split by words for very long sentences
          const words = sentence.split(/\s+/);
          let wordChunk = "";

          for (const word of words) {
            if ((wordChunk + (wordChunk ? " " : "") + word).length > maxLength) {
              if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
              // If a single word is too long (rare), split it
              if (word.length > maxLength) {
                for (let i = 0; i < word.length; i += maxLength) {
                  chunks.push(createSingleParagraphBlock(word.substring(i, i + maxLength)));
                }
                wordChunk = "";
              } else {
                wordChunk = word;
              }
            } else {
              wordChunk += (wordChunk ? " " : "") + word;
            }
          }

          if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
        } else {
          currentChunk = sentence;
        }
      } else {
        currentChunk += (currentChunk ? " " : "") + sentence;
      }
    }

    if (currentChunk) chunks.push(createSingleParagraphBlock(currentChunk));
    return chunks;
  }

  return createSingleParagraphBlock(content);
}

/**
 * Creates a single paragraph block with the given content
 * 
 * @param {string} content - The text content for the paragraph
 * @returns {Object} - A Notion paragraph block object
 */
function createSingleParagraphBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a heading block with the specified content and level
 * 
 * @param {string} content - The text content for the heading
 * @param {number} [level=1] - The heading level (1, 2, or 3)
 * @returns {Object} - A Notion heading block object
 */
function createHeadingBlock(content, level = 1) {
  content = sanitizeInput(content, "Untitled");

  // Validate level is 1, 2, or 3
  if (![1, 2, 3].includes(level)) {
    console.warn(`Invalid heading level: ${level}, defaulting to 1`);
    level = 1;
  }

  const headingType = `heading_${level}`;
  return {
    object: "block",
    type: headingType,
    [headingType]: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a bulleted list item block
 * 
 * @param {string} content - The text content for the list item
 * @returns {Object} - A Notion bulleted list item block
 */
function createBulletedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "bulleted_list_item",
    bulleted_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a numbered list item block
 * 
 * @param {string} content - The text content for the list item
 * @returns {Object} - A Notion numbered list item block
 */
function createNumberedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "numbered_list_item",
    numbered_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a divider block
 * 
 * @returns {Object} - A Notion divider block
 */
function createDividerBlock() {
  return {
    object: "block",
    type: "divider",
    divider: {}
  };
}

/**
 * Creates a code block with specified content and language
 * 
 * @param {string} content - The code content
 * @param {string} [language="plain_text"] - The programming language
 * @returns {Object} - A Notion code block
 */
function createCodeBlock(content, language = "plain_text") {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "code",
    code: {
      rich_text: [{ type: "text", text: { content } }],
      language: language
    }
  };
}

module.exports = {
  createParagraphBlock,
  createSingleParagraphBlock,
  createHeadingBlock,
  createBulletedListItemBlock,
  createNumberedListItemBlock,
  createDividerBlock,
  createCodeBlock
};

