/**
 * Notion Page Operations Routes
 * 
 * This module provides Express route handlers for additional Notion page operations including:
 * - Appending content to existing pages
 * - Updating page content by ID
 * - Creating standalone pages
 * - Archiving pages
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  sanitizeInput 
} = require('../../../api-utils');

const { 
  notionParentPageId 
} = require('../../../config');

const { 
  cache 
} = require('../../../cache');

const { 
  createHeadingBlock, 
  createParagraphBlock 
} = require('../utils/block-utils');

const { 
  findPageByTitle 
} = require('../utils/page-utils');

/**
 * @route   PATCH /append-to-page-by-title
 * @desc    Appends content to an existing page by title, or creates a new page if it doesn't exist
 * @body    {string} title - The page title to append to
 * @body    {string} content - The content to append
 * @returns {Object} JSON response with operation status
 */
router.patch("/append-to-page-by-title", async (req, res) => {
  try {
    const { title, content } = req.body;

    // Input validation
    if (!title || !content) {
      return res.status(400).json({ error: "Missing title or content." });
    }

    if (typeof title !== 'string' || typeof content !== 'string') {
      return res.status(400).json({ 
        error: "Invalid input. Title and content must be strings." 
      });
    }

    const sanitizedTitle = sanitizeInput(title);
    const sanitizedContent = sanitizeInput(content);

    if (!sanitizedTitle) {
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    console.log(`Attempting to append to page titled "${sanitizedTitle}"...`);
    const match = await findPageByTitle(sanitizedTitle);
    let pageId;

    if (!match) {
      console.warn(`Creating new page titled "${sanitizedTitle}"...`);
      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: sanitizedTitle }
              }
            ]
          }
        })
      );

      pageId = createRes.data.id;

      // Clear cache after creating a new page
      cache.clear();
    } else {
      pageId = match.page.id;
    }

    // Handle content blocks (which might be an array after splitting long content)
    const contentBlocks = createParagraphBlock(sanitizedContent);

    if (Array.isArray(contentBlocks)) {
      // If we have multiple content blocks, append them in chunks to avoid API limits
      for (let i = 0; i < contentBlocks.length; i += 10) {
        const chunk = contentBlocks.slice(i, i + 10);
        await apiCallWithRetry(() => 
          notionApi.patch(`/blocks/${pageId}/children`, {
            children: chunk
          })
        );
      }
    } else {
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: [contentBlocks]
        })
      );
    }

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ 
      success: true, 
      pageId,
      message: match ? "Content appended to existing page" : "Created new page and appended content"
    });
  } catch (error) {
    handleApiError(res, error, "append-to-page-by-title");
  }
});

/**
 * @route   PATCH /update-page
 * @desc    Updates page content by ID
 * @body    {string} pageId - The Notion page ID to update
 * @body    {string} content - The content to update
 * @returns {Object} JSON response with operation status
 */
router.patch("/update-page", async (req, res) => {
  try {
    const { pageId, content } = req.body;

    // Input validation
    if (!pageId || !content) {
      return res.status(400).json({ error: "Missing pageId or content." });
    }

    // Validate pageId format
    if (typeof pageId !== 'string' || !pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    // Validate content
    if (typeof content !== 'string') {
      return res.status(400).json({ 
        error: "Invalid content. Must be a string." 
      });
    }

    const sanitizedContent = sanitizeInput(content);

    // Handle content blocks (which might be an array after splitting long content)
    const contentBlocks = createParagraphBlock(sanitizedContent);

    if (Array.isArray(contentBlocks)) {
      // If we have multiple content blocks, append them in chunks to avoid API limits
      for (let i = 0; i < contentBlocks.length; i += 10) {
        const chunk = contentBlocks.slice(i, i + 10);
        await apiCallWithRetry(() => 
          notionApi.patch(`/blocks/${pageId}/children`, {
            children: chunk
          })
        );
      }
    } else {
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: [contentBlocks]
        })
      );
    }

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ success: true, updated: true, pageId });
  } catch (error) {
    handleApiError(res, error, "update-page");
  }
});

/**
 * @route   PUT /post-standalone-page
 * @desc    Creates a standalone page with optional content
 * @body    {string} title - The title for the new page
 * @body    {string} content - Optional content for the new page
 * @returns {Object} JSON response with creation status and page ID
 */
router.put("/post-standalone-page", async (req, res) => {
  try {
    const { title, content } = req.body;
    console.log("Received request to create standalone page with title:", title);

    // Input validation
    if (!title) {
      return res.status(400).json({ error: "Missing title." });
    }

    if (typeof title !== 'string') {
      return res.status(400).json({ 
        error: "Invalid title. Must be a string." 
      });
    }

    if (content && typeof content !== 'string') {
      return res.status(400).json({ 
        error: "Invalid content. Must be a string if provided." 
      });
    }

    const sanitizedTitle = sanitizeInput(title);
    const sanitizedContent = content ? sanitizeInput(content) : "";

    if (!sanitizedTitle) {
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    const childrenBlocks = [createHeadingBlock(sanitizedTitle)];

    // Add content if provided
    if (sanitizedContent) {
      const contentBlocks = createParagraphBlock(sanitizedContent);
      if (Array.isArray(contentBlocks)) {
        childrenBlocks.push(...contentBlocks);
      } else {
        childrenBlocks.push(contentBlocks);
      }
    }

    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { type: "page_id", page_id: notionParentPageId },
        properties: {
          title: [
            {
              type: "text",
              text: { content: sanitizedTitle }
            }
          ]
        },
        children: childrenBlocks
      })
    );

    // Invalidate cache
    cache.clear();

    res.json({ 
      success: true, 
      pageId: response.data.id,
      message: "Standalone page created successfully"
    });
  } catch (error) {
    handleApiError(res, error, "create-standalone-page");
  }
});

/**
 * @route   DELETE /page/:id
 * @desc    Archives a Notion page by ID
 * @param   {string} id - The Notion page ID to archive
 * @returns {Object} JSON response with archive status
 */
router.delete("/page/:id", async (req, res) => {
  try {
    const pageId = req.params.id;

    if (!pageId) {
      return res.status(400).json({ error: "Missing page ID." });
    }

    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        archived: true
      })
    );

    // Invalidate cache
    cache.invalidate(pageId);

    // Also remove any entries in the titles cache that might reference this page
    for (const [key] of Object.entries(cache.stores.titles)) {
      if (key === pageId) {
        cache.invalidate(key, 'titles');
        break;
      }
    }

    res.json({ 
      success: true, 
      archived: true,
      message: `Page ${pageId} archived successfully`
    });
  } catch (error) {
    handleApiError(res, error, "archive-page");
  }
});

module.exports = router;

