            hasMore = false;
            break;
          }

          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }

        cursors.length = 0;
      }
    }

    return results;
  } catch (error) {
    console.error(`❌ Pagination error for ${endpoint}:`, error.message);
    throw error;
  }
}

