          // Handle case where a single sentence is too long
          if (sentence.length > maxLength) {
            // Split by words for very long sentences
            const words = sentence.split(/\s+/);
            let wordChunk = "";

            for (const word of words) {
              if ((wordChunk + (wordChunk ? " " : "") + word).length > maxLength) {
                if (wordChunk) chunks.push(this.singleParagraph(wordChunk));
                // If a single word is too long (rare), split it
                if (word.length > maxLength) {
                  for (let i = 0; i < word.length; i += maxLength) {
                    chunks.push(this.singleParagraph(word.substring(i, i + maxLength)));
                  }
                  wordChunk = "";
                } else {
                  wordChunk = word;
                }
              } else {
                wordChunk += (wordChunk ? " " : "") + word;
              }
            }

            if (wordChunk) chunks.push(this.singleParagraph(wordChunk));
          } else {
            currentChunk = sentence;
          }
        } else {
          currentChunk += (currentChunk ? " " : "") + sentence;
        }
      }

      if (currentChunk) chunks.push(this.singleParagraph(currentChunk));
