/**
 * Notion Integration Router
 * 
 * This is the main router for the Notion integration, assembling all modular components
 * and route handlers. It serves as the entry point for all Notion-related functionality.
 * 
 * The router combines the following modules:
 * - Page routes (list, create, version)
 * - Page operations (append, update, archive)
 * - Memory routes (CRUD operations for Notion memory database)
 * - Database operations
 * - Health checks
 */

const express = require('express');
const router = express.Router();

// Import route modules
const pageRoutes = require('./routes/page-routes');
const pageOperations = require('./routes/page-operations');
const memoryRoutes = require('./routes/memory-routes');

// Import utility modules
const { notionApi, handleApiError, apiCallWithRetry } = require('./api-utils');
const { notionDatabaseId, requiredEnvVars } = require('./config');
const { cache } = require('./cache');

