// === Full Notion Integration: Core Routes + Memory Extensions ===
const express = require("express");
const router = express.Router();
const axios = require("axios");

// === Environment Variables Validation ===
const requiredEnvVars = [
  'NOTION_TOKEN', 
  'NOTION_PARENT_PAGE_ID', 
  'NOTION_DATABASE_ID', 
  'GPT_MEMORY'
];

for (const varName of requiredEnvVars) {
  if (!process.env[varName]) {
    console.error(`❌ Missing required environment variable: ${varName}`);
    process.exit(1);
  }
}

const notionToken = process.env.NOTION_TOKEN;
const notionParentPageId = process.env.NOTION_PARENT_PAGE_ID;
const notionDatabaseId = process.env.NOTION_DATABASE_ID;
const notionMemoryDBId = process.env.GPT_MEMORY;

// Configuration
const CONFIG = {
  CACHE_TTL: process.env.CACHE_TTL_MS || 1000 * 60 * 5, // 5 minutes default
  CACHE_CLEANUP_INTERVAL: process.env.CACHE_CLEANUP_INTERVAL_MS || 1000 * 60 * 10, // 10 minutes default
  CACHE_MAX_ITEMS: process.env.CACHE_MAX_ITEMS || 1000, // Maximum items in cache
  API_TIMEOUT: process.env.API_TIMEOUT_MS || 10000, // 10 seconds default
  MAX_CONTENT_LENGTH: 1800, // Maximum content length per block
  MAX_ITEMS_PER_PAGE: process.env.MAX_ITEMS_PER_PAGE || 5000,
  DEFAULT_PAGE_SIZE: process.env.DEFAULT_PAGE_SIZE || 100
};

// === Create Axios Instance with Default Configuration ===
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${notionToken}`,
    "Notion-Version": "2022-06-28",
    "Content-Type": "application/json"
  },
  timeout: CONFIG.API_TIMEOUT
});

// === Enhanced Caching Setup ===
class NotionCache {
  constructor(options = {}) {
    this.stores = {
      pages: new Map(),
      titles: new Map()
    };

    this.ttl = options.ttl || CONFIG.CACHE_TTL;
    this.maxItems = options.maxItems || CONFIG.CACHE_MAX_ITEMS;
    this.cleanupInterval = options.cleanupInterval || CONFIG.CACHE_CLEANUP_INTERVAL;
    this.lastCleanup = Date.now();

    // Start periodic cleanup
    if (options.autoCleanup !== false) {
      this.startPeriodicCleanup();
    }
  }

  startPeriodicCleanup() {
    setInterval(() => this.cleanup(), this.cleanupInterval);
  }

  set(key, value, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    // Check if at max capacity and evict oldest item if needed
    if (this.stores[type].size >= this.maxItems) {
      let oldestKey = null;
      let oldestTime = Infinity;

      for (const [k, item] of this.stores[type].entries()) {
        if (item.timestamp < oldestTime) {
          oldestTime = item.timestamp;
          oldestKey = k;
        }
      }

      if (oldestKey) {
        this.stores[type].delete(oldestKey);
        console.log(`🧹 Cache eviction: removed oldest item from ${type} store`);
      }
    }

    // Add new item
    this.stores[type].set(key, {
      value,
      timestamp: Date.now()
    });

    // Run cleanup if it's been more than the cleanup interval
    if (Date.now() - this.lastCleanup > this.cleanupInterval) {
      this.cleanup();
    }
  }

  get(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return null;
    }

    const item = this.stores[type].get(key);
    if (!item) return null;

    // Check if cache is still valid
    if (Date.now() - item.timestamp > this.ttl) {
      this.stores[type].delete(key);
      return null;
    }

    return item.value;
  }

  invalidate(key, type = 'pages') {
    if (!this.stores[type]) {
      console.warn(`Invalid cache store type: ${type}`);
      return;
    }

    this.stores[type].delete(key);
  }

  clear() {
    for (const storeType in this.stores) {
      this.stores[storeType].clear();
    }
    this.lastCleanup = Date.now();
    console.log('🧹 Cache cleared completely');
  }

  cleanup() {
    const now = Date.now();
    this.lastCleanup = now;
    let totalRemoved = 0;

    for (const [storeType, store] of Object.entries(this.stores)) {
      let storeRemoved = 0;

      for (const [key, item] of store.entries()) {
        if (now - item.timestamp > this.ttl) {
          store.delete(key);
          storeRemoved++;
        }
      }

      totalRemoved += storeRemoved;
      console.log(`🧹 Cache cleanup: removed ${storeRemoved} items from ${storeType} store`);
    }

    const stats = Object.entries(this.stores).map(([type, store]) => `${type}: ${store.size}`).join(', ');
    console.log(`🧹 Cache cleanup completed. Removed ${totalRemoved} items. Current sizes: ${stats}`);
  }

  getStats() {
    const stats = {};
    for (const [type, store] of Object.entries(this.stores)) {
      stats[type] = store.size;
    }
    return stats;
  }
}

const cache = new NotionCache();

// === Improved Error Handling Helper ===
const handleApiError = (res, error, context) => {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};

  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { errorCode: 'NO_RESPONSE', message: error.message };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }

  // Add request context to the error
  errorDetails.context = context;

  console.error(`❌ ${context} error:`, errorMessage, errorDetails);

  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context
  });
};

// === Enhanced Retry Logic with Jitter ===
async function apiCallWithRetry(fn, options = {}) {
  const maxRetries = options.maxRetries || 3;
  const baseDelay = options.baseDelay || 1000; // 1 second
  const maxDelay = options.maxDelay || 10000; // 10 seconds
  const timeoutMs = options.timeout || CONFIG.API_TIMEOUT;

  let retries = 0;

  while (true) {
    try {
      // Add timeout handling
      const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => reject(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);
      });

      const resultPromise = fn();

      // Race between the API call and the timeout
      return await Promise.race([resultPromise, timeoutPromise]);
    } catch (error) {
      const isRetryable = 
        error.response?.status === 429 || // Rate limited
        error.response?.status === 503 || // Service unavailable
        error.response?.status >= 500 ||  // Server errors
        error.code === 'ECONNRESET' ||    // Connection reset
        error.code === 'ETIMEDOUT' ||     // Connection timeout
        error.message.includes('timeout'); // Generic timeout error

      if (isRetryable && retries < maxRetries) {
        // Calculate delay with exponential backoff and jitter
        const exponentialDelay = Math.min(
          maxDelay,
          baseDelay * Math.pow(2, retries)
        );
        // Add jitter: random value between 0 and 1 * 0.5 * calculated delay
        const jitter = Math.random() * 0.5 * exponentialDelay;
        const delay = exponentialDelay + jitter;

        console.log(`API call failed with ${error.response?.status || error.code || 'unknown error'}, retrying in ${Math.round(delay)}ms... (${retries + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        // Either not retryable or max retries exceeded
        if (retries >= maxRetries) {
          console.error(`❌ Max retries (${maxRetries}) exceeded for API call. Last error:`, error.message);
        }
        throw error;
      }
    }
  }
}

// === Utility: Safely sanitize input strings ===
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;
  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }
  return input.trim();
}

// === Block Creation Helpers ===
function createParagraphBlock(content) {
  // Validate and sanitize content
  content = sanitizeInput(content, "");
  if (!content) return createSingleParagraphBlock("");

  // Split content into manageable chunks if too long
  if (content.length > CONFIG.MAX_CONTENT_LENGTH) {
    const chunks = [];
    const maxLength = CONFIG.MAX_CONTENT_LENGTH;

    // First try to split by sentences for more natural breaks
    const sentences = content.split(/(?<=[.!?])\s+/);
    let currentChunk = "";

    for (const sentence of sentences) {
      // If adding this sentence exceeds max length, create a new chunk
      if ((currentChunk + (currentChunk ? " " : "") + sentence).length > maxLength) {
        if (currentChunk) {
          chunks.push(createSingleParagraphBlock(currentChunk));
          currentChunk = "";
        }

        // Handle case where a single sentence is too long
        if (sentence.length > maxLength) {
          // Split by words for very long sentences
          const words = sentence.split(/\s+/);
          let wordChunk = "";

          for (const word of words) {
            if ((wordChunk + (wordChunk ? " " : "") + word).length > maxLength) {
              if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
              // If a single word is too long (rare), split it
              if (word.length > maxLength) {
                for (let i = 0; i < word.length; i += maxLength) {
                  chunks.push(createSingleParagraphBlock(word.substring(i, i + maxLength)));
                }
                wordChunk = "";
              } else {
                wordChunk = word;
              }
            } else {
              wordChunk += (wordChunk ? " " : "") + word;
            }
          }

          if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
        } else {
          currentChunk = sentence;
        }
      } else {
        currentChunk += (currentChunk ? " " : "") + sentence;
      }
    }

    if (currentChunk) chunks.push(createSingleParagraphBlock(currentChunk));
    return chunks;
  }

  return createSingleParagraphBlock(content);
}

function createSingleParagraphBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

function createHeadingBlock(content, level = 1) {
  content = sanitizeInput(content, "Untitled");

  // Validate level is 1, 2, or 3
  if (![1, 2, 3].includes(level)) {
    console.warn(`Invalid heading level: ${level}, defaulting to 1`);
    level = 1;
  }

  const headingType = `heading_${level}`;
  return {
    object: "block",
    type: headingType,
    [headingType]: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

// === Utility: Enhanced title extraction function ===
async function extractPageTitle(page) {
  if (!page) {
    console.warn("Cannot extract title: page object is undefined");
    return "Untitled Page";
  }

  // Check cache first
  const cacheKey = page.id;
  if (!cacheKey) {
    console.warn("Cannot cache page title: missing page ID");
    return extractTitleUncached(page);
  }

  const cachedTitle = cache.get(cacheKey, 'titles');
  if (cachedTitle) {
    return cachedTitle;
  }

  // Extract title using helper function
  const extractedTitle = await extractTitleUncached(page);

  // Cache the result
  if (extractedTitle && cacheKey) {
    cache.set(cacheKey, extractedTitle, 'titles');
  }

  return extractedTitle;
}

// Helper function for title extraction logic
async function extractTitleUncached(page) {
  // Try to extract title from properties first (for pages and databases)
  if (page.properties) {
    // Check all title-like properties in descending order of likelihood
    const titleProps = ['title', 'Name', 'Feature', 'Title'];

    for (const prop of titleProps) {
      const titleArray = page.properties[prop]?.title;
      if (titleArray && titleArray.length > 0) {
        const textContent = titleArray[0]?.plain_text || titleArray[0]?.text?.content;
        if (textContent) {
          console.log(`✅ Found title in properties.${prop}: "${textContent}"`);
          return textContent;
        }
      }
    }
  }

  // For direct title property (older Notion API format)
  if (page.title) {
    if (Array.isArray(page.title) && page.title.length > 0) {
      const textContent = page.title[0]?.plain_text || page.title[0]?.text?.content;
      if (textContent) {
        console.log(`✅ Found title in direct title array: "${textContent}"`);
        return textContent;
      }
    } else if (typeof page.title === 'string') {
      console.log(`✅ Found string title: "${page.title}"`);
      return page.title;
    }
  }

  // Try to get from page object
  if (page.child_page?.title) {
    console.log(`✅ Found title in child_page: "${page.child_page.title}"`);
    return page.child_page.title;
  }

  // Last resort: Extract from page content
  if (page.id) {
    try {
      return await extractTitleFromBlocks(page.id);
    } catch (err) {
      console.error(`❌ Failed to extract title from blocks for ${page.id}:`, err.message);
      return `Untitled Page (${page.id.substring(0, 8)})`;
    }
  }

  return `Untitled Page (${page.id ? page.id.substring(0, 8) : 'unknown'})`;
}

// === Utility: Enhanced title extraction from blocks ===
async function extractTitleFromBlocks(pageId) {
  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=50`)
    );

    const blocks = response.data.results;

    // First check for a child_page with title
    const childPageBlock = blocks.find(block => block.type === "child_page");
    if (childPageBlock?.child_page?.title) {
      const title = childPageBlock.child_page.title;
      console.log(`📄 Found child page title: ${title}`);
      return title;
    }

    // Look for the first heading block
    const headingTypes = ["heading_1", "heading_2", "heading_3"];
    const headingBlock = blocks.find(block => headingTypes.includes(block.type));

    if (headingBlock) {
      const blockType = headingBlock.type;
      const richText = headingBlock[blockType]?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        console.log(`✅ Found title in ${blockType}: "${title}"`);
        return title;
      }
    }

    // Try to get first paragraph text as fallback
    const paragraphBlock = blocks.find(block => block.type === "paragraph");
    if (paragraphBlock) {
      const richText = paragraphBlock.paragraph?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        console.log(`✅ Found title in paragraph: "${title}"`);
        return title;
      }
    }

    // Get page info directly as last resort
    try {
      const pageInfo = await apiCallWithRetry(() => 
        notionApi.get(`/pages/${pageId}`)
      );

      // Try to find any property that might contain a title
      const properties = pageInfo.data.properties;
      if (properties) {
        for (const [key, value] of Object.entries(properties)) {
          if (value.title && value.title.length > 0) {
            const title = value.title[0]?.plain_text || value.title[0]?.text?.content;
            if (title) {
              console.log(`✅ Found title in page properties.${key}: "${title}"`);
              return title;
            }
          }
        }
      }
    } catch (err) {
      console.error(`❌ Failed to fetch page info for ${pageId}:`, err.message);
    }

    console.log(`⚠️ No usable title found for ${pageId}`);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  } catch (err) {
    console.error(`❌ Title extraction failed for ${pageId}:`, err.message);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  }
}

// === Utility: Find Page by Title ===
async function findPageByTitle(title) {
  title = sanitizeInput(title);

  if (!title) {
    console.warn("Empty title provided to findPageByTitle");
    return null;
  }

  const normalizedInput = title.toLowerCase();

  // Check cache first
  const cacheKey = `title:${normalizedInput}`;
  const cachedPage = cache.get(cacheKey);
  if (cachedPage) {
    return cachedPage;
  }

  try {
    const searchResponse = await apiCallWithRetry(() => 
      notionApi.post('/search', {
        query: title,
        filter: { property: "object", value: "page" },
        page_size: 10
      })
    );

    // No results
    if (!searchResponse.data.results.length) {
      return null;
    }

    // Use the enhanced title extraction for better matching
    const pages = await Promise.all(searchResponse.data.results.map(async (page) => {
      try {
        const extractedTitle = await extractPageTitle(page);
        return {
          page,
          title: extractedTitle
        };
      } catch (err) {
        console.error(`Error extracting title for page ${page.id}:`, err.message);
        return {
          page,
          title: `Untitled (${page.id.substring(0, 8)})`
        };
      }
    }));

    // Find exact match or closest match
    const exactMatch = pages.find(item => 
      item.title && item.title.toLowerCase() === normalizedInput
    );

    const match = exactMatch || null;

    // Cache the result
    if (match) {
      cache.set(cacheKey, match);
    }

    return match;
  } catch (error) {
    console.error(`❌ Find page error for "${title}":`, error.message);
    return null;
  }
}

// === Utility: Enhanced child pages extraction ===
async function extractChildPages(pageId, pages = [], visited = new Set(), depth = 0, maxDepth = 3) {
  // Guard against invalid pageId or excessive recursion
  if (!pageId || visited.has(pageId) || depth > maxDepth) {
    return pages;
  }

  // Protect against infinite recursion
  visited.add(pageId);

  // Track recursion depth for debugging
  const indentation = "  ".repeat(depth);
  console.log(`${indentation}🔍 Exploring page ${pageId} (depth: ${depth}/${maxDepth})`);

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    );

    const blocks = response.data.results;

    const blockCount = blocks.length;
    console.log(`${indentation}🧱 Found ${blockCount} blocks in page ${pageId}`);

    // Process child pages specifically
    const childPagePromises = blocks
      .filter(block => block.type === "child_page")
      .map(async (block) => {
        const childId = block.id;

        // Skip if we already added this page
        if (pages.some(p => p.id === childId)) {
          console.log(`${indentation}⚠️ Duplicate page detected: ${childId}`);
          return null;
        }

        let childTitle = block.child_page?.title;

        // If no title in the initial response, try to extract it
        if (!childTitle || childTitle === "(no title)") {
          try {
            const pageInfo = await apiCallWithRetry(() => 
              notionApi.get(`/pages/${childId}`)
            );
            childTitle = await extractPageTitle(pageInfo.data) || childTitle || "(no title)";
          } catch (err) {
            console.error(`${indentation}❌ Failed to fetch child page info for ${childId}:`, err.message);
            childTitle = `Untitled (${childId.substring(0, 8)})`;
          }
        }

        console.log(`${indentation}📄 Found child page: ${childTitle} (ID: ${childId})`);

        return {
          id: childId,
          title: childTitle,
          parent: pageId,
          type: "page"
        };
      });

    // Wait for all promises to resolve and filter out nulls
    const childPages = (await Promise.all(childPagePromises)).filter(Boolean);

    // Add the child pages to our results
    for (const childPage of childPages) {
      pages.push(childPage);
    }

    // Process nested pages with controlled concurrency (max 3 concurrent requests)
    if (depth < maxDepth) {
      const batchSize = 3;
      for (let i = 0; i < childPages.length; i += batchSize) {
        const batch = childPages.slice(i, i + batchSize);
        await Promise.all(
          batch.map(child => 
            extractChildPages(child.id, pages, visited, depth + 1, maxDepth)
          )
        );
      }
    }

    return pages;
  } catch (err) {
    console.error(`${indentation}❌ Failed to fetch children for ${pageId}:`, err.message);
    return pages;
  }
}

// === Enhanced Pagination helper ===
async function paginatedRequest(endpoint, params = {}, options = {}) {
  const pageSize = options.pageSize || CONFIG.DEFAULT_PAGE_SIZE;
  const maxItems = options.maxItems || CONFIG.MAX_ITEMS_PER_PAGE;
  const concurrentRequests = options.concurrentRequests || 1;

  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let pageCount = 0;

  const makeRequest = async (cursor) => {
    const queryParams = { ...params, page_size: pageSize };
    if (cursor) {
      queryParams.start_cursor = cursor;
    }

    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    });

    return response.data;
  };

  // First request to get initial batch and pagination info
  try {
    const firstBatch = await makeRequest(undefined);
    results = [...firstBatch.results];
    hasMore = firstBatch.has_more;
    startCursor = firstBatch.next_cursor;
    pageCount++;

    console.log(`📊 Fetched page ${pageCount} with ${results.length} items from ${endpoint}`);

    // If we need more pages and haven't hit limits
    const cursors = [];
    while (hasMore && results.length < maxItems && pageCount < 50) {
      cursors.push(startCursor);

      // Process in batches of concurrent requests
      if (cursors.length >= concurrentRequests || !hasMore) {
        const batchResults = await Promise.all(
          cursors.map(cursor => makeRequest(cursor))
        );

        for (const data of batchResults) {
          results = results.concat(data.results || []);
          hasMore = data.has_more;
          startCursor = data.next_cursor;
          pageCount++;

          console.log(`📊 Fetched page ${pageCount} with ${data.results.length} items from ${endpoint}`);

          if (results.length >= maxItems) {
            console.warn(`⚠️ Pagination limit reached (${maxItems} items)`);
            hasMore = false;
            break;
          }

          if (pageCount >= 50) {
            console.error(`❌ Too many pages fetched (${pageCount}). Possible API issue.`);
            hasMore = false;
            break;
          }

          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }

        cursors.length = 0;
      }
    }

    return results;
  } catch (error) {
    console.error(`❌ Pagination error for ${endpoint}:`, error.message);
    throw error;
  }
}

// === Normalize keys for memory functions with better error handling ===
function normalizeKey(key) {
  if (!key) return "";

  const sanitizedKey = sanitizeInput(key, "");

  try {
    return decodeURIComponent(sanitizedKey.toLowerCase());
  } catch (e) {
    console.error(`❌ Error decoding URI component: ${key}`, e);
    return sanitizedKey.toLowerCase();
  }
}

