      timestamp: new Date().toISOString(),
      cache: cacheStats
    });
  } catch (error) {
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to connect to Notion API',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Add a catch-all route to handle invalid endpoints
